quests[82441] = { id = 82441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus Liebe zu Edelsteinen", description = "Vor dem Fall von Dalaran war ich eine der größten Experten für Edelsteine. Aber ich habe alles verloren - Edelsteine, Bücher, Schriftrollen -, so wie alle.\n\nStellt Euch meine Überraschung vor, als ich erfuhr, dass eine Kreatur namens Basalteus Wissen über Edelsteine hat, das auf die Zeit vor der Zerschlagung zurückgeht.\n\nIch will dieses Wissen. Ich würde alles dafür tun.\n\nAber diese steinhäutigen Hinterwäldler hier wollen mir nicht mehr über Basalteus verraten. Könnt Ihr die Irdenen dazu bewegen, den Mund aufzumachen?", sourceObjective = "Sammelt Informationen über Basalteus von den irdenen Dorfbewohnern.", progress = "Konntet Ihr mit ihnen sprechen? Habt Ihr irgendwelche Informationen?", completion = "Ihr habt sie zum Reden gebracht? Wunderbar! Sie wussten sogar noch mehr als gedacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82442] = { id = 82442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schein wahren", sourceObjective = "Das Werk der Durchtrennten Fäden geht rasch voran. Daher haben unsere Gönner beschlossen, Euren fortlaufenden Einsatz zu belohnen.\n\nNehmt das und verschwindet. Ihr zieht Argwohn auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
