quests[82451] = { id = 82451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plüschbegleiter bewahren" }
quests[82452] = { id = 82452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Weltquests", description = "So viel zu tun, so wenig Zeit!\n\nBrinthe und ich haben uns umgehört, welche Leute in Khaz Algar am dringendsten Hilfe brauchen. Es sind unzählige!\n\nGeht und helft ihnen. Mit Eurer Hilfe können wir unsere Leute enger zusammenbringen... auf dass wir alle stärker werden können.", sourceObjective = "Schließt Weltquests in Khaz Algar ab.", completion = "Ah! Ich habe schon so viele Späherberichte und Briefe bekommen! Das habt Ihr toll gemacht. Hoffentlich wisst Ihr, dass Ihr geschätzt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[82453] = { id = 82453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Zugabe!", description = "Habt Ihr die Flugblätter gesehen? Sie führen Theaterstücke der Irdenen im Proszenium auf!\n\nIch weiß nicht, wann ich zuletzt ein Theaterstück gesehen habe, aber ich habe wie üblich zu viel zu tun. Ihr geht doch hin?\n\nBestimmt könnten hier alle eine Aufmunterung gebrauchen. Ein Stück könnte genau das sein, was alle brauchen. Macht einen denkwürdigen Abend daraus!", sourceObjective = "Nehmt am Ereignis 'Theatertruppe' teil und schließt Weltquests in Khaz Algar ab.", completion = "Habt Ihr das Stück gesehen? War es gut? Erzählt mir alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[82454] = { id = 82454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerbadoptimierung" }
quests[82455] = { id = 82455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Brot mehr" }
quests[82456] = { id = 82456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da habt Ihr was zum Beißen" }
quests[82465] = { id = 82465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Edelsteine", description = "Dann haben sie uns also nur einen Ort und ein unverständliches Rätsel gegeben...\n\nWenigstens wissen wir jetzt, wo wir anfangen sollen.\n\nIch kann es schon vor mir sehen. Sobald ich Basalteus' Wissen habe, werden Adlige und Händler vor meinem Haus Schlange stehen. Nein, vor meinem Anwesen!\n\nDie Irdenen sprachen von Südwesten, oder? Ich finde die Höhle und treffe Euch dort. Beeilt Euch!", sourceObjective = "Trefft Euch mit Natalia vor Basalteus' Höhle.", completion = "Seht Euch die Wände dieser Höhle an. Und seht Euch all diese Edelsteine an! Ich kann es kaum fassen! Die Geschichte muss wahr sein!\n\nIch werde reich! Und einflussreich! Und mächtig!\n\nIch muss mich erst mal kurz hinsetzen und durchatmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82466] = { id = 82466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was man für Edelsteine tut", description = "Den Irdenen zufolge müssen wir den Geist herlocken. Oder ihn stören. Etwas in der Art.\n\nUm die vier Menhire, die sie erwähnten, liegen leere Elementarkerne herum. Draußen und auf dem Strand im Norden treiben sich feurige Elementare herum. Denkt Ihr, was ich denke?\n\nKönntet Ihr mir Elementarkerne besorgen? Nur ein paar vielleicht? Wir sind schon so nah dran, einen Versuch ist es wert...", sourceObjective = "Sammelt 4 Elementarkerne von den Feurigen Sandelementaren.", progress = "Habt Ihr die Kerne?", completion = "Vier Kerne für vier Menhire.\n\nIch bin bereit, wenn Ihr es seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[82467] = { id = 82467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine sind ewig", description = "Ich bin so nah dran, ich kann es in den Knochen spüren.\n\nPlatziert die Kerne neben den einzelnen Menhiren. Wir müssen Basalteus beschwören.", sourceObjective = "Lockt Basalteus an, indem Ihr einen Kern neben jeden der Menhire legt.", progress = "Das ist es. Ich kann es spüren.", completion = "Das war wirklich einfach! Für mich zumindest.\n\nKönnt Ihr Euch vorstellen, was ich mit diesem Wissen anfangen kann? Könnt Ihr Euch vorstellen, meinen Namen in Sturmwind zu hören? In Gilneas? Vielleicht sogar in Orgrimmar?\n\nIch werde alles tun, alles erreichen können, was ich je wollte. Endlich werden alle zu mir aufblicken. Ich werde alles Gold haben, um alles finden und erschaffen zu können!", sourceObjectiveStatus = "unverified-source-field" }
quests[82468] = { id = 82468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewinnen lassen" }
quests[82470] = { id = 82470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rätsel" }
quests[82477] = { id = 82477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe auf dem Hof", sourceObjective = "Holt 8 leicht angekaute Feldfrüchte von den gefräßigen Kieferkriechern zurück.", progress = "Damit ist unsere Ernte in Zukunft geschützt. Und vielleicht können wir die Reste... einkochen.", completion = "Gute Arbeit, {name}, das sieht... essbar aus. Und wenn man auf der Mauer steht und fürchtet, dass die Neruber einen umbringen werden, wird sich wohl niemand daran stören. \n\nWährend Ihr tätig wart, konnte ich eine Menge von ELIZAs Entscheidungszahnrädern richtig ausrichten, also danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[82478] = { id = 82478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geplante Wartungsarbeiten", sourceObjective = "Bringt Orrens Nachricht, 6 Blutrote Bezauberer und 6 Bernblüten zu Aemyra in Velhans Geltung.", progress = "Die sind von Orren? Ich finde, sie passen gut zusammen, obwohl sie so verschieden sind.", completion = "Wow, das ist wirklich nett von ihm. Ich werde noch eine Weile hier sein und mich um die Kobyss kümmern, aber ich sollte ihm etwas zurückschicken.\n\nDamit er weiß, dass ich in Sicherheit bin und es kaum erwarten kann, ihn zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82479] = { id = 82479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwert ist mächtiger", sourceObjective = "Helft Aemyra, die richtigen Worte für Ihre Nachricht an Orren zu finden.", completion = "Wie ich mich freue, dass es ihr gut geht! Aber jetzt habe ich ein Riesenproblem.", sourceObjectiveStatus = "unverified-source-field" }
quests[82480] = { id = 82480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roboter außer Kontrolle", sourceObjective = "Stoppt ELIZA.", completion = "ELIZA hat nicht so funktioniert, wie ich erwartet hatte. Aber Aemyra glaubt, dass ich es hinkriegen werde... Ich werde es weiter versuchen.\n\nUnd wenn ich es schaffe, wird Nahrungsmangel keine Gefahr für die Arathi mehr sein - und Zeitmangel wird mich nicht mehr von Aemyra fernhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[82481] = { id = 82481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollstreckervernichtung" }
quests[82482] = { id = 82482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Schnüffeln", description = "Ich will schon so lange die Höhlen von Heilsturz erforschen. Natürlich habe ich kaum Zeit, aber einst... Es ist alles voller Überraschungen!\n\nSchätze, Freunde in Not, starke und schwache Gegner... Alles ganz wunderbar.\n\nIch muss eben indirekt durch Euch leben. Es gibt so viel zu tun! Geht und sucht in allen Winkeln nach Überraschungen. Bestimmt findet Ihr Dinge, die getan werden müssen!", sourceObjective = "Findet Haufen aufgewühlter Erde zum Schnüffeln und entdeckt Weltenseelenpartikel beim Himmelsreiten über Khaz Algar.", completion = "Unsere Welt ist ein wundervoller Ort. Habt Dank, dass Ihr sie beschützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82483] = { id = 82483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Verbreitung des Lichts", description = "In Heilsturz breitet sich die Dunkelheit aus. Wir brauchen Eure Hilfe, damit die Feuer weiterbrennen!\n\nDie Schatten sind tief und finster. Mein Volk ist stark, aber wir brauchen doch mehr Hoffnung. Mehr Funken für die Flamme. Ihr seid der hellste Funke von allen.", sourceObjective = "Schließt die Ziele 'Verbreitung des Lichts' ab und tötet seltene Kreaturen in Khaz Algar.", completion = "<Faerin atmet auf.> \n\nSelbst hier... kann ich es fast spüren: Beledars Kraft kehrt zurück. Ihr habt geholfen, die Dunkelheit zurückzudrängen.\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[82485] = { id = 82485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Metbrauerei Glutbräu", description = "Ah, Glutbräu. Es ist wirklich so stark und feurig, wie man behauptet.\n\nIch könnte mir vorstellen, dass Beledar so schmecken würde...\n\nDie Irdenen lieben es! Und es ist ein wichtiger Teil ihres Erbes. Deshalb dürfen wir nicht zulassen, dass ihre Metbrauerei in die falschen Hände gerät.\n\nAber... nehmt Euch vor den Glutbienen in Acht. Ich habe gehört, dass ihre Stacheln... nun ja, ich will Euch damit keine Angst einjagen. Aber ich bin froh, dass ich das Euch überlasse.", sourceObjective = "Schließt den Dungeon 'Metbrauerei Glutbräu' auf Schwierigkeitsgrad 'Normal' oder höher ab.", completion = "Wurdet Ihr von einer Biene gestochen? Habt Ihr das Brennen gespürt? Vielleicht seid Ihr allergisch.\n\n<Faerin kichert.>\n\nWas? Der Witz war nicht komisch? Dann macht es doch besser!", sourceObjectiveStatus = "unverified-source-field" }
quests[82486] = { id = 82486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Die Brutstätte", description = "Diese Sturmkrähen, die die Irdenen hegen, sind ein wahrlich wundervoller Anblick! Solch atemberaubendes Gefieder, solch starke Persönlichkeiten!\n\nEs muss eine Ehre sein, sich um diese Kreaturen kümmern zu dürfen. Aber es soll Ärger in der Brutstätte der Sturmreiter und ihrem Hauptquartier, dem Sturmhort, geben. Viel weiß ich nicht darüber, aber unsere Verbündeten bei den Irdenen wären sicher dankbar für jede Hilfe, die wir ihnen geben können.\n\nGeht dem nach, {name}.Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Brutstätte' auf Schwierigkeitsgrad 'Normal' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82487] = { id = 82487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Das Steingewölbe", description = "Brinthe war eine großartige Hilfe dabei, die Arathi und die Irdenen wieder zusammenzubringen. Sie hat mir berichtet, was ihrem Volk in den Schallenden Tiefen widerfahren ist.\n\nIch kann... ihre Frustration darüber verstehen, welche Richtung Eure Leute einschlagen. Zum Glück ist Stahlstoß eine vernünftigere Anführerin als dieser... Oberste Sprecher Eirich.\n\nEirich ist in das Steingewölbe geflohen, um seine Truppen zu sammeln. Es würde Brinthe und ihrem Volk viel bedeuten, wenn Ihr ihm folgen würdet, um ihn aufzuhalten!", sourceObjective = "Schließt den Dungeon 'Steingewölbe' auf Schwierigkeitsgrad 'Normal' oder höher ab.", completion = "Brinthe und ich haben von Eurem Erfolg gehört!\n\nAls neue Oberste Sprecherin wird Brinthe ihr Volk sicher mit größerer Anmut leiten als Eirich.", sourceObjectiveStatus = "unverified-source-field" }
quests[82488] = { id = 82488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Dunkelflammenspalt", description = "Kobolde! Sie können grausame Kerlchen sein, aber... Ach, ich fühle mich irgendwie mit ihnen verbunden!\n\nIhre kleinen Kerzen... Wie sie ihre Flammen schüren...\n\n<Faerin fasst sich mit einem Grinsen ans Herz.>\n\nSo mutig! Sie wären ideale Lampenanzünder, wenn sie doch nur teilen würden! Und... weniger geneigt wären, uns die Augen auszukratzen.\n\nBerichte über ihre Aktivitäten im Dunkelflammenspalt beunruhigen die Irdenen. Ich würde mir zwar wünschen, die Kobolde wären freundlicher, doch wir dürfen nicht zulassen, dass sie unsere Verbündeten verletzen. Bitte geht der Sache nach!Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Dunkelflammenspalt' auf Schwierigkeitsgrad 'Normal' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82489] = { id = 82489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Die Morgenbringer", description = "Die Morgenbringer... das Opus Magnus der Arathi von Heilsturz. Das Schiff, das alle Kriege beenden soll.\n\nEs ist bereit, in See zu stechen. Werdet Ihr sie begleiten? Viele würden sich ihr gern in den Weg stellen.", sourceObjective = "Schließt den Dungeon 'Die Morgenbringer' auf dem Schwierigkeitsgrad 'Normal' oder höher ab.", completion = "Unsere Schiffe sind Zeichen der Kreativität und Genialität der Arathi von Heilsturz.\n\nTrotz aller Widrigkeiten streben wir noch immer nach der Schönheit. Das liebe ich am meisten an meinem Volk.", sourceObjectiveStatus = "unverified-source-field" }
quests[82490] = { id = 82490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Priorat der Heiligen Flamme", description = "Mein Volk war dem Licht schon immer sehr verbunden. Ich hielt diesen Glauben einst für unerschütterlich. Aber es gibt einige...\n\n<Faerin hält inne und ringt um Worte.>\n\nEinige finden, der Glaube sollte... erzwungen werden. Damit haben die Arathi immer gehadert, auch als das Reich noch existierte.\n\nAber die Dinge liefen aus dem Ruder. Diese... Fanatiker haben das Priorat der Heiligen Flamme übernommen. Sie verletzen andere!\n\nDas hat mit dem Licht nichts zu tun, {name}. Haltet sie auf.Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Priorat der Heiligen Flamme' auf Schwierigkeitsgrad 'Normal' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82491] = { id = 82491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Ara-Kara, Stadt der Echos", description = "Informationen aus Azj-Kahet erreichen uns eher in Form von... Gemunkel als in Form von Berichten. Wir brauchen mehr Informationen!\n\nEs gibt Hinweise auf eine Stadt unter der Stadt. Sie trägt den Namen Ara-Kara. Wir wissen nichts Genaues, doch irgendetwas wird dort unten mit Schwarzblut gemacht.\n\nWir müssen herausfinden, was dort vor sich geht. Sammelt Eure stärksten Begleiter und geht der Sache auf den Grund!", sourceObjective = "Schließt den Dungeon 'Ara-Kara, Stadt der Echos' auf Schwierigkeitsgrad 'Normal' oder höher ab.", completion = "Ihr seid zurück! Ich war besorgt. Erzählt mir alles.\n\n<Faerin begutachtet Euch.>\n\nDiese Spinnen haben... Euch doch nichts getan, oder? Keine... Eier unter Eurem Umhang gelegt oder ähnliches?\n\n<Faerin schaudert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[82492] = { id = 82492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Stadt der Fäden", description = "Xal'atath hat den Nerubern das schwarze Blut \"geschenkt\", damit sie zu etwas noch Schlimmerem aufsteigen konnten, als sie es ohnehin schon waren.\n\nWir müssen die Unruhe in der Stadt nutzen. Sammelt Eure Verbündeten und bereitet Euch auf die Infiltration vor... wir müssen sie aufhalten!", sourceObjective = "Schließt den Dungeon 'Stadt der Fäden' auf Schwierigkeitsgrad 'Normal' oder höher ab.", completion = "So viele Spinnen. So viele Beine.\n\n<Faerin schüttelt sich.>\n\nIch vermute, Ihr habt Euch gut gehalten. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[82493] = { id = 82493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Die Morgenbringer", description = "Die Morgenbringer... das Opus Magnus der Arathi von Heilsturz. Das Schiff, das alle Kriege beenden soll.\n\nEs ist bereit, in See zu stechen. Werdet Ihr sie begleiten? Viele würden sich ihr gern in den Weg stellen.", sourceObjective = "Schließt den Dungeon 'Die Morgenbringer' auf Schwierigkeitsgrad 'Heroisch' oder höher ab.", completion = "Unsere Schiffe sind Zeichen der Kreativität und Genialität der Arathi von Heilsturz.\n\nTrotz aller Widrigkeiten streben wir noch immer nach der Schönheit. Das liebe ich am meisten an meinem Volk.", sourceObjectiveStatus = "unverified-source-field" }
quests[82494] = { id = 82494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Ara-Kara, Stadt der Echos", description = "Informationen aus Azj-Kahet erreichen uns eher in Form von... Gemunkel als in Form von Berichten. Wir brauchen mehr Informationen!\n\nEs gibt Hinweise auf eine Stadt unter der Stadt. Sie trägt den Namen Ara-Kara. Wir wissen nichts Genaues, doch irgendetwas wird dort unten mit Schwarzblut gemacht.\n\nWir müssen herausfinden, was dort vor sich geht. Sammelt Eure stärksten Begleiter und geht der Sache auf den Grund!", sourceObjective = "Schließt den Dungeon 'Ara-Kara, Stadt der Echos' auf Schwierigkeitsgrad 'Heroisch' oder höher ab.", completion = "Ihr seid zurück! Ich war besorgt. Erzählt mir alles.\n\n<Faerin begutachtet Euch.>\n\nDiese Spinnen haben... Euch doch nichts getan, oder? Keine... Eier unter Eurem Umhang gelegt oder ähnliches?\n\n<Faerin schaudert.>", sourceObjectiveStatus = "unverified-source-field" }
