quests[82498] = { id = 82498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Dunkelflammenspalt", description = "Kobolde! Sie können grausame Kerlchen sein, aber... Ach, ich fühle mich irgendwie mit ihnen verbunden!\n\nIhre kleinen Kerzen... Wie sie ihre Flammen schüren...\n\n<Faerin fasst sich mit einem Grinsen ans Herz.>\n\nSo mutig! Sie wären ideale Lampenanzünder, wenn sie doch nur teilen würden! Und... weniger geneigt wären, uns die Augen auszukratzen.\n\nBerichte über ihre Aktivitäten im Dunkelflammenspalt beunruhigen die Irdenen. Ich würde mir zwar wünschen, die Kobolde wären freundlicher, doch wir dürfen nicht zulassen, dass sie unsere Verbündeten verletzen. Bitte geht der Sache nach!Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Dunkelflammenspalt' auf Schwierigkeitsgrad 'Heroisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82499] = { id = 82499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Priorat der Heiligen Flamme", description = "Mein Volk war dem Licht schon immer sehr verbunden. Ich hielt diesen Glauben einst für unerschütterlich. Aber es gibt einige...\n\n<Faerin hält inne und ringt um Worte.>\n\nEinige finden, der Glaube sollte... erzwungen werden. Damit haben die Arathi immer gehadert, auch als das Reich noch existierte.\n\nAber die Dinge liefen aus dem Ruder. Diese... Fanatiker haben das Priorat der Heiligen Flamme übernommen. Sie verletzen andere!\n\nDas hat mit dem Licht nichts zu tun, {name}. Haltet sie auf.Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Priorat der Heiligen Flamme' auf Schwierigkeitsgrad 'Heroisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82500] = { id = 82500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Die Brutstätte", description = "Diese Sturmkrähen, die die Irdenen hegen, sind ein wahrlich wundervoller Anblick! Solch atemberaubendes Gefieder, solch starke Persönlichkeiten!\n\nEs muss eine Ehre sein, sich um diese Kreaturen kümmern zu dürfen. Aber es soll Ärger in der Brutstätte der Sturmreiter und ihrem Hauptquartier, dem Sturmhort, geben. Viel weiß ich nicht darüber, aber unsere Verbündeten bei den Irdenen wären sicher dankbar für jede Hilfe, die wir ihnen geben können.\n\nGeht dem nach, {name}.Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Brutstätte' auf Schwierigkeitsgrad 'Heroisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82501] = { id = 82501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Die Morgenbringer", description = "Die Morgenbringer... das Opus Magnus der Arathi von Heilsturz. Das Schiff, das alle Kriege beenden soll.\n\nEs ist bereit, in See zu stechen. Werdet Ihr sie begleiten? Viele würden sich ihr gern in den Weg stellen.Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Die Morgenbringer' auf Schwierigkeitsgrad 'Mythisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82502] = { id = 82502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Ara-Kara, Stadt der Echos", description = "Informationen aus Azj-Kahet erreichen uns eher in Form von... Gemunkel als in Form von Berichten. Wir brauchen mehr Informationen!\n\nEs gibt Hinweise auf eine Stadt unter der Stadt. Sie trägt den Namen Ara-Kara. Wir wissen nichts Genaues, doch irgendetwas wird dort unten mit Schwarzblut gemacht.\n\nWir müssen herausfinden, was dort vor sich geht. Sammelt Eure stärksten Begleiter und geht der Sache auf den Grund!Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Ara-Kara, Stadt der Echos' auf Schwierigkeitsgrad 'Mythisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82503] = { id = 82503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Metbrauerei Glutbräu", description = "Ah, Glutbräu. Es ist wirklich so stark und feurig, wie man behauptet.\n\nIch könnte mir vorstellen, dass Beledar so schmecken würde...\n\nDie Irdenen lieben es! Und es ist ein wichtiger Teil ihres Erbes. Deshalb dürfen wir nicht zulassen, dass ihre Metbrauerei in die falschen Hände gerät.\n\nAber... nehmt Euch vor den Glutbienen in Acht. Ich habe gehört, dass ihre Stacheln... nun ja, ich will Euch damit keine Angst einjagen. Aber ich bin froh, dass ich das Euch überlasse.Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Metbrauerei Glutbräu' auf Schwierigkeitsgrad 'Mythisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82504] = { id = 82504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Stadt der Fäden", description = "Xal'atath hat den Nerubern das schwarze Blut \"geschenkt\", damit sie zu etwas noch Schlimmerem aufsteigen konnten, als sie es ohnehin schon waren.\n\nWir müssen die Unruhe in der Stadt nutzen. Sammelt Eure Verbündeten und bereitet Euch auf die Infiltration vor... wir müssen sie aufhalten!Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Stadt der Fäden' auf Schwierigkeitsgrad 'Mythisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82505] = { id = 82505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Das Steingewölbe", description = "Brinthe war eine großartige Hilfe dabei, die Arathi und die Irdenen wieder zusammenzubringen. Sie hat mir berichtet, was ihrem Volk in den Schallenden Tiefen widerfahren ist.\n\nIch kann... ihre Frustration darüber verstehen, welche Richtung Eure Leute einschlagen. Zum Glück ist Stahlstoß eine vernünftigere Anführerin als dieser... Oberste Sprecher Eirich.\n\nEirich ist in das Steingewölbe geflohen, um seine Truppen zu sammeln. Es würde Brinthe und ihrem Volk viel bedeuten, wenn Ihr ihm folgen würdet, um ihn aufzuhalten!Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Das Steingewölbe' auf Schwierigkeitsgrad 'Mythisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82506] = { id = 82506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Dunkelflammenspalt", description = "Kobolde! Sie können grausame Kerlchen sein, aber... Ach, ich fühle mich irgendwie mit ihnen verbunden!\n\nIhre kleinen Kerzen... Wie sie ihre Flammen schüren...\n\n<Faerin fasst sich mit einem Grinsen ans Herz.>\n\nSo mutig! Sie wären ideale Lampenanzünder, wenn sie doch nur teilen würden! Und... weniger geneigt wären, uns die Augen auszukratzen.\n\nBerichte über ihre Aktivitäten im Dunkelflammenspalt beunruhigen die Irdenen. Ich würde mir zwar wünschen, die Kobolde wären freundlicher, doch wir dürfen nicht zulassen, dass sie unsere Verbündeten verletzen. Bitte geht der Sache nach!Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Dunkelflammenspalt' auf Schwierigkeitsgrad 'Mythisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82507] = { id = 82507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Priorat der Heiligen Flamme", description = "Mein Volk war dem Licht schon immer sehr verbunden. Ich hielt diesen Glauben einst für unerschütterlich. Aber es gibt einige...\n\n<Faerin hält inne und ringt um Worte.>\n\nEinige finden, der Glaube sollte... erzwungen werden. Damit haben die Arathi immer gehadert, auch als das Reich noch existierte.\n\nAber die Dingen liefen aus dem Ruder. Diese... Fanatiker haben das Priorat der Heiligen Flamme übernommen. Sie verletzen andere!\n\nDas hat mit dem Licht nichts zu tun, {name}. Haltet sie auf.Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Priorat der Heiligen Flamme' auf Schwierigkeitsgrad 'Mythisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82508] = { id = 82508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Die Brutstätte", description = "Diese Sturmkrähen, die die Irdenen hegen, sind ein wahrlich wundervoller Anblick! Solch atemberaubendes Gefieder, solch starke Persönlichkeiten!\n\nEs muss eine Ehre sein, sich um diese Kreaturen kümmern zu dürfen. Aber es soll Ärger in der Brutstätte der Sturmreiter und ihrem Hauptquartier, dem Sturmhort, geben. Viel weiß ich nicht darüber, aber unsere Verbündeten bei den Irdenen wären sicher dankbar für jede Hilfe, die wir ihnen geben können.\n\nGeht dem nach, {name}.Ihr erlernt:", sourceObjective = "Schließt den Dungeon 'Brutstätte' auf Schwierigkeitsgrad 'Mythisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82509] = { id = 82509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Palast der Nerub'ar", description = "Königin Ansurek hat sich als ebenso grausam wie gewieft entpuppt. Wir dürfen nicht zulassen, dass ihre Truppen durch Xal'ataths Schwarzblut stärker werden.\n\nNun, es ist soweit. Eine gewaltige Aufgabe, fürwahr. Mit unserer größten Streitmacht werden wir den Palast der Nerub'ar belagern!Ihr erlernt:", sourceObjective = "Schließt den Schlachtzug 'Palast der Nerub'ar' auf dem Schwierigkeitsgrad 'Schlachtzugbrowser' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82510] = { id = 82510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Palast der Nerub'ar", description = "Königin Ansurek hat sich als ebenso grausam wie gewieft entpuppt. Wir dürfen nicht zulassen, dass ihre Truppen durch Xal'ataths Schwarzblut stärker werden.\n\nNun, es ist so weit. Eine gewaltige Aufgabe, fürwahr. Mit unserer größten Streitmacht werden wir den Palast der Nerub'ar belagern!Ihr erlernt:", sourceObjective = "Schließt den Schlachtzug 'Palast der Nerub'ar' auf dem Schwierigkeitsgrad 'Heroisch' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82511] = { id = 82511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Erweckungsmaschine", description = "Die Irdenen haben mir von dieser \"Erweckungsmaschine\" erzählt, die Teil ihres Lebenszyklus ist.\n\nSie erfüllt sie mit Energie, die einst ein Geschenk der Titanen war, jetzt aber von der Weltenseele kommt.\n\n<Faerin lächelt schwach und nickt wissend.>\n\nSie verehren sie hoch, wie wir Beledar.\n\nIch werde sie mit demselben Eifer verteidigen, wie ich unseren eigenen Stern verteidigen würde!\n\nHelft mir, {name}. Wir können sie nicht im Stich lassen.", sourceObjective = "Bezwingt 20 kumulative Gegnerwellen in der Erweckungsmaschine.", completion = "Wundervoll! Ich bin sicher, unsere Verbündeten bei den Irdenen wissen Eure Hilfe zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82512] = { id = 82512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Weltboss", description = "Heilsturz ist nicht das einzige Land, das von Feinden heimgesucht wird.\n\nGroße Monster durchstreifen ganz Khaz Algar, sowohl wilde Tiere als auch intelligente Unholde. Sie töten Arathi, Irdene und Abenteurer gleichermaßen. Von unschuldigen Bauern zu großen Kriegern.\n\nIch weiß, die Heilige Flamme brennt in Euch. Ihr seid unsere beste Hoffnung bei der Jagd dieser großen Übel.", sourceObjective = "Besiegt einen beliebigen Weltboss sowie 5 seltene Kreaturen in Khaz Algar.", completion = "Wie ist es Euch ergangen? Irgendwelche neuen Narben? Oder neue Geschichten zu erzählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[82516] = { id = 82516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: einen Pakt schmieden", description = "Ich habe Berichte darüber gehört, was in Azj-Kahet vor sich geht. Seit unserer Ankunft haben die Neruber mein Volk gnadenlos getötet... ich kann sie mir nur schwer als Verbündete vorstellen.\n\nAber... ich kenne das Gefühl... anders zu sein als der Rest des eigenen Volkes. Vielleicht sind diese Neruber, die sich für uns interessieren, ebenfalls... anders.\n\n<Faerin seufzt.>\n\nWas es auch kostet... Ich muss ihnen einfach eine Chance geben. Sind sie nicht ebenfalls Bewohner von Khaz Algar?\n\nSeht, welche Hilfe Ihr ihnen anbieten könnt.", sourceObjective = "Wählt einen Pakt mit den Durchtrennten Fäden zum Repräsentieren in Azj-Kahet aus, schließt in ihrem Namen Ziele ab und tötet seltene Gegner in Khaz Algar.", completion = "Gut seht Ihr aus. Schön, dass Ihr kein Spinnenfraß geworden seid.\n\n<Faerin zupft stirnrunzelnd einen Spinnwebfetzen von Eurer Schulter.>", sourceObjectiveStatus = "unverified-source-field" }
