quests[82539] = { id = 82539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strahlende Echos", sourceObjective = "Trefft Khadgar in Dalaran.", completion = "Danke, dass Ihr gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[82540] = { id = 82540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen an frühere Abenteuer", description = "Offenbar ist Azeroth... aufgeregt? Bei Magnis Kommunikationsversuch muss etwas geschehen sein.\n\nVergangene Ereignisse sind wieder lebendig. Sie sind wohl Azeroths Erinnerungen.\n\nJedenfalls sind diese strahlenden Echos nur allzu wirklich und könnten gefährlich werden, wenn sich niemand um sie kümmert. Bitte untersucht ein Echo und helft, so gut Ihr könnt.", sourceObjective = "Begebt Euch in die Porträtgalerie in Dalaran und benutzt ein leuchtendes Portal, um am Ereignis \"Strahlende Echos\" teilzunehmen. Sobald es beginnt, tötet den Territoriumsboss, um das Ereignis abzuschließen.", progress = "Strahlende Echos, strahlende Visionen, alles erscheint zugleich. Was will Azeroth uns sagen? Oder ist es nur... Instinkt?", completion = "Vorzügliche Arbeit, {name}. Helft weiter mit den strahlenden Echos und sucht nach einer Gemeinsamkeit. Es muss einen Zusammenhang geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[82544] = { id = 82544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Within (80) E" }
