quests[82628] = { id = 82628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brüder Braunspyß", description = "Baron Braunspyß und sein Bruder arbeiten daran, unser lästiges Kobyssproblem bei den Ehrengründen zu beheben.\n\nTrefft sie dort und findet heraus, wie Ihr helfen könnt.", sourceObjective = "Trefft die Brüder Braunspyß bei den Ehrengründen.", completion = "Hoffentlich kommt Ihr, um Euch die Hände schmutzig zu machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[82629] = { id = 82629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Palast der Nerub'ar: Nur für Neruberaugen", description = "Unsere Tunnel wurden nicht für Euresgleichen gebaut... zu tückisch, um sich alleine hindurchzuwagen.\n\nBringt mir Signets vom Seidenhof, vom Skarabäusfürsten Anub'arash und von Strangspinnerin Takazj, dann zeige ich Euch eine Geheimpassage zum Palast.", sourceObjective = "Sammelt 3 Signets der tausend Narben und 3 Signets des Strangspinners im Palast der Nerub'ar auf Schwierigkeitsgrad 'Normal'.", progress = "Die sichere Passage hat ihren Preis.", completion = "Geratet nicht in die Schatten, {name} - ich garantiere nicht für Eure Sicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[82638] = { id = 82638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Palast der Nerub'ar: Nur für Neruberaugen", description = "Unsere Tunnel wurden nicht für Euresgleichen gebaut... zu tückisch, um sich alleine hindurchzuwagen.\n\nBringt mir Signets vom Seidenhof, vom Skarabäusfürsten Anub'arash und von Strangspinnerin Takazj, dann zeige ich Euch eine Geheimpassage zum Palast.", sourceObjective = "Sammelt 3 Signets der tausend Narben und 3 Signets des Strangspinners im Palast der Nerub'ar auf Schwierigkeitsgrad 'Heroisch'.", progress = "Die sichere Passage hat ihren Preis.", completion = "Geratet nicht in die Schatten, {name} - ich garantiere nicht für Eure Sicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[82639] = { id = 82639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Palast der Nerub'ar: Nur für Neruberaugen", description = "Unsere Tunnel wurden nicht für Euresgleichen gebaut... zu tückisch, um sich alleine hindurchzuwagen.\n\nBringt mir Signets vom Seidenhof, vom Skarabäusfürsten Anub'arash und von Strangspinnerin Takazj, dann zeige ich Euch eine Geheimpassage zum Palast.", sourceObjective = "Sammelt 3 Signets der tausend Narben und 3 Signets des Strangspinners im Palast der Nerub'ar auf Schwierigkeitsgrad 'Mythisch'.", sourceObjectiveStatus = "unverified-source-field" }
quests[82650] = { id = 82650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prise Salz" }
quests[82653] = { id = 82653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ansammlung der Schrecken" }
quests[82658] = { id = 82658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen lassen und rennen" }
quests[82659] = { id = 82659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltenseele: Palast der Nerub'ar", description = "Königin Ansurek hat sich als ebenso grausam wie gewieft entpuppt. Wir dürfen nicht zulassen, dass ihre Truppen durch Xal'ataths Schwarzblut stärker werden.\n\nNun, es ist so weit. Eine gewaltige Aufgabe, fürwahr. Mit unserer größten Streitmacht werden wir den Palast der Nerub'ar belagern!Ihr erlernt:", sourceObjective = "Schließt den Schlachtzug 'Palast der Nerub'ar' auf Schwierigkeitsgrad 'Normal' oder höher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[82672] = { id = 82672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine weitere zeitige Einladung", description = "Der bronzene Drachenschwarm hält eine Feier außerhalb der Höhlen der Zeit in Tanaris ab!\n\nEs gibt allerlei neue Aktivitäten, an denen Ihr teilnehmen könnt, um das zu ehren und dem zu gedenken, was sich im Verlauf der Jahre ereignet hat.\n\nBegebt Euch nach Tanaris und nehmt an den Feierlichkeiten teil.", sourceObjective = "Besucht die Feierlichkeiten in Tanaris außerhalb der Höhlen der Zeit.", completion = "Willkommen!\n\nEs ist diese besondere Zeit des Jahres, während der bronzene Drachenschwarm alles feiert, was sich über die Jahre ereignet hat.\n\nIhr, {name}, gehört zu unseren ehrwürdigsten Gästen!", sourceObjectiveStatus = "unverified-source-field" }
quests[82676] = { id = 82676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochene Maskerade", description = "Ich weiß nicht, wie ich zu diesem Sumpf gelangt bin, aber es war ein Glück. Unterwegs erblickte ich Lady Katrana Prestor, wie sie eine seltsame Höhle mit Zähnen betrat. Was tut eine Edle wie sie an so einem grausigen Ort?\n\nIch ging ihr nach und fand zahlreiche schwarze Dracheneier im Hort. Es ist eindeutig: Katrana ist Lady Onyxia!\n\nIch bitte Euch, helft mir, diesen bösen Großdrachen ein für alle Mal zu besiegen.", sourceObjective = "Besiegt die Unvergessene Onyxia bei einem Ereignis 'Strahlende Echos'.", progress = "Wäre Varian doch hier. Er hätte kein Problem, sie zu erschlagen.", completion = "Ist es wahr? Sie ruht endlich?\n\nSie hatte unbeugsamen Ehrgeiz. Gut, dass wir sie gestoppt haben. Nicht auszudenken, welche Tragödien ihre finsteren Machenschaften bewirkt hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[82678] = { id = 82678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archive: Die erste Scheibe", description = "Ich freue mich, berichten zu können, dass die Wiederherstellung der titanischen Kammer der Erinnerung im Archiv Fortschritte gemacht hat. Ich habe den Hauptrechner wieder zum Laufen gebracht, aber ein Teil des internen Mechanismus ist im Laufe der Zeit ausgefallen.\n\nEs wird eine Herausforderung sein, Ersatzteile dafür zu bekommen, und darum brauchen wir Eure Hilfe. Begleitet mich zur Kammer der Erinnerung. Wir können mit Dagran besprechen, was wir benötigen.", sourceObjective = "Trefft Dagran in der Kammer der Erinnerung und helft ihm, Titanscheibenfragmente zu finden.\n\nDiese Scheibenfragmente können in Dungeons, Tiefen und von gefährlichen Kreaturen und Schätzen in ganz Khaz Algar erbeutet werden.", progress = "Habt Ihr vielleicht etwas gefunden?", completion = "Die sind perfekt! Bei diesen Teilen ist die Korrosion minimal. Wir sollten sämtliche Informationen retten können, die sie enthalten!\n\nJetzt legen wir seit langem vergrabenes Wissen frei, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[82679] = { id = 82679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archive: Geschichte suchen", description = "Wir bearbeiten immer noch die Daten im Archiv und stellen wieder her, was wir können. Aber... die Scheiben, die wir bislang im Archiv selbst geborgen haben, sind unbrauchbar.\n\nEs hat Priorität, mehr von diesen Scheiben zu finden. Wir müssen unsere Erinnerungen zurückgewinnen.\n\nBringt Dagran, was immer Ihr findet. Er hilft mir bei der Wiederherstellung des Archivs.", sourceObjective = "Sammelt 100 Titanscheibenfragmente.\n\nDiese Scheibenfragmente können in Dungeons, Tiefen und von gefährlichen Kreaturen und Schätzen in ganz Khaz Algar erbeutet werden.", progress = "Habt Ihr was gefunden?", completion = "Mehr davon! Ich frage mich, was wir dieses Mal entdecken werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[82680] = { id = 82680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vogelmann der Drei Schilde", description = "Seid Ihr hier, um die Mooswollen zu sehen? Nein?\n\nZu schade. Ich finde die Elementarwesen unserer Insel faszinierend. Da bin ich nicht der Einzige.\n\nEin alter Freund namens Olbarig lebt draußen auf den Drei Schilden, wo er die wilden Wolkenkrähen studiert.\n\nWenn ich so darüber nachdenke, habe ich schon eine Weile nichts mehr von ihm gehört. Vielleicht sollte mal jemand nach ihm sehen. Hm. Wärt Ihr so gut?", sourceObjective = "Finde Olbarig auf den Drei Schilden.", completion = "Harmot hat Euch geschickt, um nach mir zu sehen?\n\nHm. Nun, es wäre mir neu, dass dieser Kohlesack sich um mich schert.\n\nEr hat allerdings ein feines Gespür dafür, wann die Elementare in Aufruhr geraten. Vielleicht wusste er, dass sich hier etwas zusammenbraut.\n\nHarmot hat den richtigen Zeitpunkt gewählt. Ich wäre Euch sehr dankbar für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[82681] = { id = 82681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolkenkrähensturz", description = "Seht Ihr den Schwarm dort in der Ferne? Wilde Wolkenkrähen.\n\nSie leben schon seit Ewigkeiten friedlich auf diesen Inseln. Aber die jüngsten Ereignisse haben andere Erd- und Meereselementare aufgeschreckt. Eine der Wolkenkrähen wurde angegriffen und... aufgelöst.\n\nJetzt zieht der Schwarm endlose Kreise. Sie werden sicher bald müde, und wenn sie zu müde werden...\n\nWenn wir die feindlichen Elementare von der Insel beseitigen, werden sie vielleicht zurückkehren und sich ausruhen.", sourceObjective = "Erlegt die verärgerten Elementare vom zentralen Schild.", progress = "Das ist der Lebensraum der Wolkenkrähen. Euer Absturz und unser Krieg gegen die Neruber haben dafür gesorgt, dass die anderen Elementare herkamen.\n\nWir sollten die Angelegenheit in Ordnung bringen.", completion = "Vielen Dank für Eure Hilfe, Fremder. Allerdings scheinen die Wolkenkrähen noch immer nicht an Land zurückkehren zu wollen.\n\nWenn dies ihre Art zu trauern ist, fürchte ich, dass die Krähen sich schließlich selbst auflösen, wenn sie bis zur Erschöpfung fliegen.\n\nWir müssen etwas anderes versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82682] = { id = 82682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Hors d'oeuvres", description = "Die Wolkenkrähen können unmöglich ewig weiterkreisen, und ich ertrage es nicht, noch mehr von ihnen zu verlieren. Vielleicht würden sie rasten, wenn wir sie mit ihrem Lieblingsfutter anlocken?\n\nDie Aale in diesen Gewässern tragen eine kleine elektrische Ladung in sich, ähnlich wie die Mooswollen, die ihre schnelleren, stärkeren Verwandten, die Sturmkrähen, bevorzugen. Ich überlegte einmal, ob Wolkenkrähen die Aale vielleicht aus ähnlichen Gründen mögen würden.\n\nUnd ich muss zugeben... Seither füttere ich sie mit diesen Aalen.\n\nSammelt einige und gebt sie ihnen.", sourceObjective = "Sammelt 10 Zitteraale.", progress = "Die Aale sind vielleicht nicht so geladen wie Bummelgaumooswolle, aber die Wolkenkrähen scheinen sie so lieber zu mögen.", completion = "Das sollte reichen.\n\nHoffentlich habt Ihr beim Sammeln keinen Schlag bekommen.\n\nWir können den Wolkenkrähen etwas Energie zurückgeben und ihnen zeigen, dass sie jetzt sicher landen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[82689] = { id = 82689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Dunkelheit", description = "Lange habe ich auf diesen Tag gewartet. Seid Ihr und Eure Verbündeten bereit, den Lichkönig zur Rechenschaft zu ziehen? Auf Euren Befehl stürmen wir los!", sourceObjective = "Besiegt den Unvergessenen Lichkönig bei einem Ereignis 'Strahlende Echos'.", progress = "Wir kämpfen um das Schicksal Azeroths. Um das Licht des Morgens!", completion = "Dann ist es also endlich vollbracht.\n\nMögen die Völker Azeroths unserer Taten hier ewig gedenken. Mögen die Opfer so vieler für immer in ihren Herzen brennen. Mögen sie im Angesicht großer Bedrohungen nie die Bereitschaft verlieren, ihr Leben für andere zu riskieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[82690] = { id = 82690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verweilende Schatten", description = "Als wir Xal'ataths Streitkräften in Heilsturz gegenüberstanden, spürte ich etwas Dunkles direkt unter der Oberfläche. Etwas, das nicht sie war, aber es beunruhigt mich dennoch.\n\nIch habe gelernt, dass es nicht immer die beste Taktik ist, selbst in jede Situation zu stürmen. Manchmal muss sich ein Anführer zurückhalten, um das Feld zu überblicken.\n\nDeshalb schicke ich Euch.\n\nGeht nach Heilsturz und findet alles über die mysteriöse Macht heraus, was Ihr könnt. Ich will nicht noch einmal unvorbereitet erwischt werden.", sourceObjective = "Kehrt dorthin zurück, wo Alleria in Heilsturz Schwarzblut gespürt hat.", completion = "Mit Euch hatte ich hier nicht gerechnet.\n\nAber Ihr schafft es ja immer, dort aufzutauchen, wo es etwas Interessantes gibt, nicht wahr?\n\nDoch für Plaudereien ist keine Zeit. Mein Volk steckt in Schwierigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[82691] = { id = 82691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Verschnaufpause", description = "Wir folgten Orweyna alle zu diesen Oberflächenhöhlen, weil wir an unsere Taten glaubten. Aber das... Mit so vielen Verletzungen, so verbissener Suche hatten wir nicht gerechnet.\n\nIm Moment brauchen wir eine Verschnaufpause. Tötet die Kreaturen da draußen, die uns schaden, und wir können uns den Freiraum schaffen, um das eigentliche Problem anzugehen.", sourceObjective = "Tötet die durchsickernden Kreaturen.", progress = "Unser Volk ist kämpferisch und stark. Wir sind es gewohnt, in der Unterzahl zu sein. Aber das ist zu viel.", completion = "Das sollte uns etwas Raum zum Rückzug geben.\n\nUnd nun müssen wir uns mit dem Kern des Problems befassen. Das heißt, Orweynas immerwährende Entschlossenheit, diese Mission zu verfolgen, koste es, was es wolle.\n\nEs wird Zeit, dass wir uns unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[82692] = { id = 82692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis einer Mission", description = "Ich weiß nicht, was Euch veranlasst hat, hierher zu kommen, aber wir könnten Eure Hilfe gebrauchen.\n\nWir sind gekommen, um die Anzeichen von Schwarzblut in diesem Gebiet zu untersuchen, aber die Kreaturen haben uns überwältigt. Einige von uns sind immer noch draußen auf dem Feld.\n\nIhr seid gesund und munter. Geht und findet meine Leute, damit sie zurückkehren können.\n\nUnd wenn Ihr die Kraft habt, seht Euch die seltsamen Pflanzen genauer an, die aus dem Blut wachsen, das in der Erde versickert. Sie könnten einen Hinweis darauf geben, wie wir die Verderbnis bekämpfen können.", sourceObjective = "Findet die festgenagelten Haranir und untersucht die seltsamen Pflanzen.", completion = "<Orweyna zählt im Stillen die Anzahl der Haranir, um sich zu vergewissern. Dann nickt sie.>\n\nDas sind alle. Ich bin Euch so dankbar.\n\nDiese Pflanzen, die Ihr gefunden habt, sind äußerst seltsam. Sie scheinen ihre Eigenschaften verloren zu haben und zu etwas Neuem geworden zu sein. Ich muss das noch genauer untersuchen.\n\nWir können jetzt nicht aufhören. Nicht, wenn wir so nah dran sind. Dies könnte der Schlüssel zu unserem Sieg sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[82693] = { id = 82693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hindernis", description = "Einige dieser Kreaturen sind stärker als andere. Als wir gemeinsam und frisch in den Kampf ziehen konnten, waren diese Kreaturen keine Bedrohung. Jetzt machen uns unsere Verletzungen und die Tatsache, dass wir getrennt sind, verwundbar.\n\nMein Volk ist widerstandsfähig, aber wir sind nicht unsterblich.\n\nEs gibt eine Bestie, die größer ist als alle anderen. Diese Bestie macht es den Haranir schwer, zurückzukehren und sich zu erholen.\n\nVernichtet sie, damit sie in Sicherheit sind.", sourceObjective = "Besiegt den Behemoth der Blutkrusten.", completion = "<Orweyna nickt.>\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[82694] = { id = 82694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsam, allein", description = "Ich bin nicht blind. Ich weiß, dass sie müde und erschöpft sind. Aber wir sind so nah dran, herauszufinden, was wir gegen das Schwarzblut tun können.\n\nDie Bedeutung unserer Entdeckungen geht über Heilsturz oder das Königreich der Neruber hinaus. Es gibt noch so viel zu tun, wenn wir eine Lösung finden wollen.\n\nFürs Erste sollten wir uns zurückziehen und erholen. Irgendwo weit weg von diesen Kreaturen.", sourceObjective = "Trefft Euch mit Hannan in Heilsturz und erfahrt dort von dem Plan.", completion = "Na'layro. Kai'shae. Ney'leia. On'hiea.\n\nHannan.\n\nWir waren eine Familie, ganz allein, hier, weit weg von zu Hause.\n\nIch mache ihnen keine Vorwürfe, dass sie zurückkehren wollen, aber ich würde mir selbst die Schuld geben, wenn ich jetzt aufgäbe. Ich muss mich auf das konzentrieren, was als nächstes kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82695] = { id = 82695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme", description = "Hier muss ich mich konzentrieren. Ich kann die Stimme meiner Göttin hören. Sie muss in der Nähe sein.\n\nIch werde mich in eine Meditation begeben und fragen, was ich tun muss. Wie kann ich diese Mission allein fortsetzen? Wie kann ich ohne die anderen weitermachen?\n\nBleibt in der Nähe, ich weiß nicht, was mir während meiner Meditation auflauern könnte.", sourceObjective = "Verteidigt Orweyna, während sie meditiert.", completion = "Ich verstehe.\n\nWir müssen an einen Ort gehen, an dem ich die Bewegungen unter den Steinen hören kann. Ich weiß nicht, was das bedeutet, ich weiß nur, dass ich dorthin gehen muss.\n\nWerdet Ihr mich begleiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[82696] = { id = 82696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallen in den Tiefen", description = "Meine Vision war klar. Ich muss diese Arbeit fortsetzen.\n\nIch muss herausfinden, wie wir die Ausbreitung des Schwarzbluts verhindern können, bevor es für Euer und mein Volk zu spät ist.\n\nTrefft mich in den Schallenden Tiefen. Ihr werdet mich in einer Gestalt vorfinden, die es mir ermöglicht, mich zu verstecken und zu lauschen, ohne dass es jemand bemerkt.", sourceObjective = "Trefft Euch mit Orweyna in Camp Murroch in den Schallenden Tiefen.", completion = "Überall scheinen Goblins zu lauern.\n\nRichtet Euren Blick nicht auf mich, Ihr erregt sonst nur Aufmerksamkeit. Wir müssen näher an die arbeitenden Goblins herankommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82697] = { id = 82697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Qual der Personalwahl", description = "Was für eine willkommene Überraschung, Euch hier zu sehen!\n\nAn der Chancenspitze ist etwas Großes im Gange, aber es ist schwer zu sagen, was, ohne näher an die Arbeitenden zu kommen.\n\nIch weiß, dass Haxel involviert ist. Wir brauchen seine Papiere, wenn wir uns ohne Probleme umhören wollen.\n\nEr ist auf dem Weg zur Chancenspitze.\n\nFolgt ihm, und seht nach, ob er etwas bei sich hat, das wir gebrauchen können. Macht Euch keine Sorgen wegen etwaiger Unordnung... Ich weiß, dass Ihr diskret seid, wenn es nötig ist.\n\nOder... wenn es nötig ist, auch nicht.", sourceObjective = "Findet Haxel Bohrzahn und nehmt ihn aus, um Zugang zur Operation zu erhalten.", progress = "Habt Ihr den Arbeitsauftrag? Damit werden sich uns viel mehr Türen öffnen.", completion = "Perfekt. Jetzt können wir etwas vorweisen, falls uns jemand fragt, warum wir hier sind. Jetzt ist es an der Zeit, ein wenig herumzuschnüffeln.\n\nHier wimmelt es ja förmlich von Goblins. Irgendetwas ist definitiv im Gange.", sourceObjectiveStatus = "unverified-source-field" }
quests[82698] = { id = 82698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurzschluss und Kampfeslust", description = "Ich habe in der Nähe viele Maschinen gesehen, und alle scheinen schreckliche Geräusche zu machen. Die, die ich in der Vision gehört habe, kann ich allerdings nicht hören, zumindest nicht deutlich.\n\nVernichtet die überflüssigen. Sie sind nur im Weg.\n\nWährend Ihr für Ruhe sorgt, werde ich auf Jagd gehen und mich weiter umsehen.", sourceObjective = "Zerstört die durchgeknallten Ausgräber.", completion = "Ihr scheint Euch auch für das Büro des Vorarbeiters zu interessieren, was?\n\nKeine Sorge, wir sind auf der gleichen Seite. Nur komme ich nicht nah genug heran, ohne gesehen zu werden.\n\nUnd dann gibt es noch einen großen, klirrenden Haken an der ganzen Sache.", sourceObjectiveStatus = "unverified-source-field" }
quests[82699] = { id = 82699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He, was ist los?", description = "Zeit, sich zu vernetzen. \n\nVor der Chancenspitze, in der Abyssausgrabung, gibt es einige Goblins. Ich habe einige von ihnen murren gehört, bevor sie ihre Schicht antraten. \n\nSehen wir nach, was wir mit einigen freundlichen Worten herausfinden können. \n\nÜberprüft die verbrauchten Treibstofffässer, wenn Ihr unterwegs seid. Sie wollten mich nicht in die vollen Fässer sehen lasen, aber die verbrauchten stehen einfach so in der Gegend rum.", sourceObjective = "Befragt Goblins und deckt Beweise in der Abyssausgrabung auf, um an Hinweise zu gelangen.", completion = "Diese Goblins kennen nur einen Teil der Geschichte. Dort drin steckt sie ganz, oder zumindest ein großer Teil von ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[82700] = { id = 82700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Explosionsgarantie", description = "Wir haben ein Informationsproblem, aber wir haben auch ein Klapperproblem.\n\nDa drüben steht ein großer, durchgeknallter Mech, der außer Kontrolle ist. Es ist unmöglich, dass irgendjemand irgendetwas aufdeckt, solange der da draußen im Einsatz ist.\n\nDagegen sollten wir etwas unternehmen.", sourceObjective = "Zerstört den durchgeknallten MEK IV.", completion = "Wir sind wohl alle auf der Suche nach Informationen, aber ich habe einige, die ich für nützlich erachte.\n\nUnd jetzt ist es zu spät, sich zu verstecken, sie haben meine wahre Gestalt gesehen.\n\nWir müssen das bis zum Ende durchstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82701] = { id = 82701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fledermaus gegen Welt", description = "Bei meinen Erkundungen habe ich Dinge gehört und gesehen, die ich nicht verstehe.\n\nWenn ich es Euch und den Goblins beschreibe, könnt Ihr daraus vielleicht eine Bedeutung erkennen.", sourceObjective = "Erlebt Orweynas Erkundungsmission.", completion = "Nachdem ich von diesem Ort geflohen war, sah ich, wie Ihr gegen die gigantische Maschine gekämpft habt, und ich musste mich dem Kampf anschließen.\n\nNun scheint es wirklich kein Zurück mehr zu geben. Ich bin hier allein, abgesehen von Euch und diesen Goblins.", sourceObjectiveStatus = "unverified-source-field" }
quests[82702] = { id = 82702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefundene Freunde", description = "Gallywix hat sich also entschieden, sein hässliches Gesicht hier zu zeigen, und wie es aussieht, hat er sich organisiert.\n\nWir sollten das Alleria melden. Mal sehen, wie sie damit verfahren will.", sourceObjective = "Erstattet Alleria in Dornogal Bericht.", completion = "Ihr habt mir weit mehr als nur Informationen gebracht. \n\nAber ich habe das Gefühl, dass diese... Orweyna... ihre Geheimnisse nicht so einfach preisgeben wird. Ich muss mich in Geduld üben. Ich bin sicher, dass wir irgendwann eine gemeinsame Basis finden werden.\n\nIn der Zwischenzeit gibt es jemanden, mit dem sie reden sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[82706] = { id = 82706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefen: Weltweite Forschung", description = "In letzter Zeit ist alles ruhig. Mir sind keine Probleme zu Ohren gekommen.\n\nDas ist die Gelegenheit für Erkundungen, oder? Ich bin bereit! Wir können gehen, wohin Ihr wollt!", sourceObjective = "Schließt 3 Tiefen in The War Within ab.", progress = "Gefährliche Erkundung? Ums nackte Überleben kämpfen? Da fühlt sich dieser alte Zwerg lebendig!", completion = "Da haben wir heute ein paar hübsche Orte zu erkunden. Das ist immer eine gute Sache. Da kommt mein altes Blut in Wallung.", sourceObjectiveStatus = "unverified-source-field" }
quests[82707] = { id = 82707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großzügige Tiefen", description = "Wir bezeichnen einige dieser Tiefen als besonders \"großzügig\", da die Fieslinge in ihnen mehr Schätze als üblich horten.\n\nDiese Schätze lassen sich nur mit ganz besonderen Schlüsseln aufsperren, die Ihr in ganz Khaz Algar finden könnt.\n\nWir haben von einem Steinriesen gehört, der in den Bergen sein Unwesen treibt und in dem so ein Schlüssel festzustecken scheint.\n\nSchnappt Euch den Schlüssel und macht Euch dann auf in eine großzügige Tiefe. Mal sehen, was Ihr dort unten findet! Wir sehen uns unten.", sourceObjective = "Holt Euch den Schlüssel von Felsenhauer und schließt danach eine großzügige Tiefe ab.", completion = "Nichts kann Brann und {name} aufhalten!\n\nHmm, {name} und Brann? Weiß nicht, was besser klingt. Ich schreib's auf die Liste.", sourceObjectiveStatus = "unverified-source-field" }
quests[82708] = { id = 82708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großzügige Tiefen", description = "Wir bezeichnen einige dieser Tiefen als besonders \"großzügig\", da die Fieslinge in ihnen mehr Schätze als üblich horten.\n\nDiese Schätze lassen sich nur mit ganz besonderen Schlüsseln aufsperren, die Ihr in ganz Khaz Algar finden könnt.\n\nWir haben von einem Steinriesen gehört, der in den Bergen sein Unwesen treibt und in dem so ein Schlüssel festzustecken scheint.\n\nSchnappt Euch den Schlüssel und macht Euch dann auf in eine großzügige Tiefe. Mal sehen, was Ihr dort unten findet! Wir sehen uns unten.", sourceObjective = "Holt Euch den Schlüssel von Felsenhauer und schließt danach eine großzügige Tiefe ab.", completion = "Jetzt werden die Neruber sich nicht mehr so viel rausnehmen, was?\n\nIhr bereitet sie vor, ich mach sie fertig! Oder andersrum. Ich bin nicht wählerisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[82709] = { id = 82709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großzügige Tiefen", description = "Wir bezeichnen einige dieser Tiefen als besonders \"großzügig\", da die Fieslinge in ihnen mehr Schätze als üblich horten.\n\nDiese Schätze lassen sich nur mit ganz besonderen Schlüsseln aufsperren, die Ihr in ganz Khaz Algar finden könnt.\n\nWir haben von einem Steinriesen gehört, der in den Bergen sein Unwesen treibt und in dem so ein Schlüssel festzustecken scheint.\n\nSchnappt Euch den Schlüssel und macht Euch dann auf in eine großzügige Tiefe. Mal sehen, was Ihr dort unten findet! Wir sehen uns unten.", sourceObjective = "Holt Euch den Schlüssel von Felsenhauer und schließt danach eine großzügige Tiefe ab.", progress = "Ich kann nicht glauben, dass manchen Leuten die eigene Geschichte egal ist. Da werd ich traurig.", completion = "Wir haben vielleicht nur Fragmente bekommen, {name}. Aber aus Fragmenten kann man das Ganze wieder zusammensetzen. Man kann sehen, was einst war.\n\nFragmente sind besser als Staub, mehr sag ich nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82710] = { id = 82710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großzügige Tiefen", description = "Wir bezeichnen einige dieser Tiefen als besonders \"großzügig\", da die Fieslinge in ihnen mehr Schätze als üblich horten.\n\nDiese Schätze lassen sich nur mit ganz besonderen Schlüsseln aufsperren, die Ihr in ganz Khaz Algar finden könnt.\n\nWir haben von einem Steinriesen gehört, der in den Bergen sein Unwesen treibt und in dem so ein Schlüssel festzustecken scheint.\n\nSchnappt Euch den Schlüssel und macht Euch dann auf in eine großzügige Tiefe. Mal sehen, was Ihr dort unten findet! Wir sehen uns unten.", sourceObjective = "Holt Euch den Schlüssel von Felsenhauer und schließt danach eine großzügige Tiefe ab.", completion = "Ich verstehe einfach nicht, warum jemand die Arathi angreifen würde. Alle dort sind für die Offensive ausgebildet!\n\nKlingt ziemlich dumm, die anzugreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82711] = { id = 82711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großzügige Tiefen", description = "Wir bezeichnen einige dieser Tiefen als besonders \"großzügig\", da die Fieslinge in ihnen mehr Schätze als üblich horten.\n\nDiese Schätze lassen sich nur mit ganz besonderen Schlüsseln aufsperren, die Ihr in ganz Khaz Algar finden könnt.\n\nWir haben von einem Steinriesen gehört, der in den Bergen sein Unwesen treibt und in dem so ein Schlüssel festzustecken scheint.\n\nSchnappt Euch den Schlüssel und macht Euch dann auf in eine großzügige Tiefe. Mal sehen, was Ihr dort unten findet! Wir sehen uns unten.", sourceObjective = "Holt Euch den Schlüssel von Felsenhauer und schließt danach eine großzügige Tiefe ab.", progress = "Ich freue mich schon drauf, diesen hässlichen Hut abzusetzen!", completion = "Oh, mein Hut... Ich liebe dich, Hut.\n\nUnd das andere Zeug auch. Das liebe ich auch. Nur nicht so sehr wie meinen Hut.", sourceObjectiveStatus = "unverified-source-field" }
quests[82712] = { id = 82712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großzügige Tiefen", description = "Wir bezeichnen einige dieser Tiefen als besonders \"großzügig\", da die Fieslinge in ihnen mehr Schätze als üblich horten.\n\nDiese Schätze lassen sich nur mit ganz besonderen Schlüsseln aufsperren, die Ihr in ganz Khaz Algar finden könnt.\n\nWir haben von einem Steinriesen gehört, der in den Bergen sein Unwesen treibt und in dem so ein Schlüssel festzustecken scheint.\n\nSchnappt Euch den Schlüssel und macht Euch dann auf in eine großzügige Tiefe. Mal sehen, was Ihr dort unten findet! Wir sehen uns unten.", sourceObjective = "Holt Euch den Schlüssel von Felsenhauer und schließt danach eine großzügige Tiefe ab.", completion = "Das ist eine... bemerkenswert wörtliche Interpretation meiner Worte, {name}.\n\nAber wir haben ihnen gezeigt, wie gefährlich es ist, so aggressiv zu werden – die Aggression geht postwendend zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[82739] = { id = 82739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtränke", description = "Der Einfluss des Schattenhammers in den Schwarzfelstiefen wächst. Sie haben sich mit den Dunkeleisenzwergen verbündet und wollen sie überreden, auch außerhalb des Berges zuzuschlagen.\n\nWir müssen die Instrumente des aufwieglerischen Schattenhammers vernichten. Ihr Einfluss auf die Dunkeleisenzwerge muss eingeschränkt werden.\n\nIch möchte, dass Ihr in die Domizile der Schwarzfelstiefen geht und mit dieser Fackel die Bücher verbrennt, die der Schattenhammer dort verteilt.", sourceObjective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[82740] = { id = 82740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtränke", description = "Der Einfluss des Schattenhammers in den Schwarzfelstiefen wächst. Sie haben sich mit den Dunkeleisenzwergen verbündet und wollen sie überreden, auch außerhalb des Berges zuzuschlagen.\n\nWir müssen die Instrumente des aufwieglerischen Schattenhammers vernichten. Ihr Einfluss auf die Dunkeleisenzwerge muss eingeschränkt werden.\n\nIch möchte, dass Ihr in die Domizile der Schwarzfelstiefen geht und mit dieser Fackel die Bücher verbrennt, die der Schattenhammer dort verteilt.", sourceObjective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[82746] = { id = 82746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großzügige Tiefen", description = "Wir bezeichnen einige dieser Tiefen als besonders \"großzügig\", da die Fieslinge in ihnen mehr Schätze als üblich horten.\n\nDiese Schätze lassen sich nur mit ganz besonderen Schlüsseln aufsperren, die Ihr in ganz Khaz Algar finden könnt.\n\nWir haben von einem Steinriesen gehört, der in den Bergen sein Unwesen treibt und in dem so ein Schlüssel festzustecken scheint.\n\nSchnappt Euch den Schlüssel und macht Euch dann auf in eine großzügige Tiefe. Mal sehen, was Ihr dort unten findet! Wir sehen uns unten.", sourceObjective = "Holt Euch den Schlüssel von Felsenhauer und schließt danach eine großzügige Tiefe ab.", completion = "Jawoll! Wir kamen, wir sahen, wir traten ihnen ins Gesicht!\n\nKhaz Algar ist jetzt sicherer vor den Angriffen dieser Mistviecher. Nicht schlecht für einen Tag, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[82747] = { id = 82747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreuzwegplatz", description = "Hallo, Fremdling. Wünscht Ihr Neuigkeiten von außerhalb der Stadt?\n\nDas Wegekreuz ist ein wichtiger Ort für Irdene, um Informationen und Güter auszutauschen, Bündnisse hin, Edikte her.\n\nMein Freund Bondaz kümmert sich inoffiziell um den Platz. Er würde Euch gerne persönlich treffen. Gewiss hat er schon hundert verschiedene Geschichten darüber gehört, wie Ihr und die Fremdlinge unsere Insel erreicht habt.", sourceObjective = "Trefft Bondaz auf dem Platz in Wegekreuz.", completion = "...Ein Fremdling? Ihr seid ja echt! Genau wie die anderen, die vorbeigekommen sind. Es gibt so viele von Euch!\n\nNicht zu glauben. Ich weiß alles über die Insel, aber das hätte ich nie gedacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82748] = { id = 82748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefbeuteschlucht", description = "Wir haben Berichte erhalten, dass es in den Tiefen der Irdenen Ärger gibt. Erkundet die Tiefbeuteschlucht und die verfügbaren Ressourcen, dann meldet Euch bei Grobius.", sourceObjective = "Schließt das Schlachtfeld 'Tiefbeuteschlucht' ab.", completion = "Ihr habt es durch die Minen geschafft! Vortrefflich!", sourceObjectiveStatus = "unverified-source-field" }
quests[82762] = { id = 82762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock im Blick", description = "Wow!\n\nWas für ein superschicker Wappenrock! Und Ihr bekommt ihn so, wie Ihr es Euch vorstellt.\n\nKessa wird Euch dabei behilflich sein, Eure Entwürfe zum Leben zu erwecken.\n\nSchaut mal bei ihr vorbei, um loszulegen!", sourceObjective = "Sprecht mit Kessa im Siegreichen Antlitz.", completion = "Ich bin gerne dabei behilflich, Euren persönlichen Wappenrock zu gestalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[82768] = { id = 82768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolkenangeln", description = "Jetzt, da wir die Aale haben, können wir versuchen, die Wolkenkrähen wieder an Land zu locken. \n\nBegebt Euch zur benachbarten Insel. Geht so nah wie möglich zu den Krähen und bietet ihnen die Aale an. \n\nMit etwas Glück hören sie auf zu kreisen und kommen zur Mahlzeit herunter.", sourceObjective = "Bietet 7 Zitteraale den wilden Wolkenkrähen an.", progress = "Nichts geht über Zitteraale, um eine müde und hungrige Wolkenkrähe zu besänftigen.", completion = "Jetzt verstehe ich. So bringen die Krähen die anderen von der Elemtarebene hierher. Sie haben nicht unbedingt getrauert, sondern viel eher nach ihren Verwandten gerufen.\n\nDanke für Eure Hilfe, Fremder. Ihr habt mir geholfen, diese schönen Kreaturen besser zu verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82771] = { id = 82771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermächtnis der Irdenen", description = "Zeit, sich bei den Archiven zu revanchieren. Alle irdenen Wanderer sind eingeladen, ihre Erlebnisse mitzuteilen, damit bewahrt werden kann, was war, und verbessert, was kommt. Dieses Wissen und die Kenntnisse der großen weiten Welt Azeroth sind unbezahlbar, und diesen Schatz zu teilen ist der Schlüssel zu unserem irdenen Vermächtnis.", sourceObjective = "Tragt mit Euren Erlebnissen zu den Archiven in Dornogal bei.", progress = "Habt Ihr Eure Erlebnisse schon beigetragen?", completion = "Wir können Euch nicht genug für dieses Geschenk danken. Eure Erlebnisse werden unschätzbar für die Irdenen sein, die gerade in den Schallenden Tiefen erwachen. Bitte nehmt dies und tragt es stolz auf Euren Reisen bei den Völkern von Azeroth und jenseits davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[82773] = { id = 82773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein funktionaler Gefallen", description = "Ich suche meinen Mentor, Vorarbeiter Arbauch. Er wird... vermisst. Unter anderen Umständen würde ich einen Suchtrupp aus Gundargaz losschicken, aber dafür ist keine Zeit.\n\nVermutlich ist er hier entlang gekommen, doch die einzige Spur ist DelGizmo. Er will, dass jemand die örtlichen Nebelbestien beseitigt. Widerwille. Aber wenn er Arbauch gesehen hat, muss ich in Erfahrung bringen, was er weiß.\n\nDie Lauerer im Süden haben mächtige Galvanische Drüsen. Sie sind geladen genug, um den dichtesten Nebel zu vertreiben. Holt mir welche. Bezahlung garantiert.", sourceObjective = "Sammelt 6 Galvanische Drüsen.", progress = "Ist nicht schlimm, wenn‘s schnell geht. Ich muss Arbauch finden.", completion = "Genehmigt. Sie sehen recht energiegeladen aus. Damit könnt Ihr die Nebelbestien für DelGizmo vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[82774] = { id = 82774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antineblinisch", description = "Maschinenflüsterer mögen keine Nebelbestien. Denn wo Nebel ist, ist Rost vorprogrammiert. Trotzdem würde ich es vorziehen, ihnen keinen Schaden zuzufügen. Arbauch sagte immer, das bringe Unglück.\n\nNehmt dieses Gerät. Die Drüsen, die Ihr gesammelt habt, sollten genug Energie liefern, um den Nebel zu zerstreuen, ohne die Nebelbestien darin zu verletzen.\n\nAber lasst Vorsicht walten! Nebelbestien sind scheu, und es können auch andere Kreaturen dort lauern.", sourceObjective = "Vertreibt den Nebel um Camp Murroch.", completion = "Gute Arbeit. Hoffentlich sind DelGizmos Informationen die Mühe wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[82775] = { id = 82775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister des schnellen Kostümwechsels", sourceObjective = "Lasst Euch von Wendeline im Proszenium Tipps geben.", completion = "In Eurem Kostüm steckt genauso viel Charakter wie in Eurer Darbietung.\n\nDas schnelle An- und Ausziehen von Kostümen zu üben, ist genauso wichtig wie Texte lernen.\n\nNun könnt Ihr im Nu in andere Rollen schlüpfen und seid ein Virtuose der Vielseitigkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[82778] = { id = 82778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelfest von Heilsturz", sourceObjective = "Fangt diese Trophäenfische, bevor der Festflitzer-Buff ausläuft: Knabberelritze, Arathorhammerfisch, Königinnenköderrücken.", completion = "Das sind ein paar gute Fänge, {name}. Ich freue mich schon darauf, was Ihr nächste Woche an Land zieht!", sourceObjectiveStatus = "unverified-source-field" }
quests[82781] = { id = 82781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Rampenlicht", sourceObjective = "Lasst Euch von Elma im Proszenium Tipps geben.", completion = "Mit Fans muss man vorsichtig umgehen. Man muss ihre Gefühle berücksichtigen, aber gleichzeitig unerwünschte Verhaltensweisen unterbinden.\n\nDer Schlüssel dazu liegt in einer freundlichen und wohlwollenden Anerkennung ihrer Dankbarkeit. Ein einfaches Dankesschreiben ist die ideale Antwort. Und wenn man Fans begegnet, ist es akzeptabel, zu nicken und zu winken. Denn selbstverständlich wollen wir, dass unser Publikum glücklich ist!\n\nUnd falls jemand Blumen mitbringt... so kann ich Euch die Last gerne abnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82782] = { id = 82782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Authentisch gekleidet", sourceObjective = "Sprecht mit Rabaan im Proszenium.", completion = "Ausgezeichnet. Ich freue mich über jedes Hindernis zwischen einem Schauspieler und seiner Weisung, das ich aus dem Weg räumen kann.\n\nBehandelt die Kostüme mit Sorgfalt. Denkt daran, dass wir sie noch für künftige Stücke brauchen.\n\nViel Glück! Und nicht vergessen: Ihr gehört jetzt zur Truppe!", sourceObjectiveStatus = "unverified-source-field" }
quests[82783] = { id = 82783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromies Kodex", description = "Hallöchen! Ich könnte wirklich Eure Hilfe brauchen. \n\nNun, mein Kodex ist bei all meinen Reisen in letzter Zeit ganz schön durcheinandergekommen, und ich muss in einer Stunde eine Zeitführung zurück zu den Pforten von Ahn'Qiraj veranstalten.\n\nIhr müsstet zusammen mit mir reinspringen und alle... Ungereimtheiten beseitigen. Dann sollte alles wieder im Lot sein und die Besucher eine spaßige, nicht supergefährliche Führung bekommen!", sourceObjective = "Schließt das Ereignis \"Chromies Kodex\" ab.", progress = "Puh, das war für einen Moment ziemlich brenzlig. Ich dachte kurz, dass Ihr es nicht schaffen würdet!", completion = "Vielen Dank für die Hilfe!\n\nIch freue mich schon so auf meine erste Führung. Dank Euch ist es nur VIEL wahrscheinlicher, dass niemand stirbt oder verloren geht. Nicht, dass das je passiert wäre...", sourceObjectiveStatus = "unverified-source-field" }
quests[82784] = { id = 82784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resonante Darbietung", sourceObjective = "Sprecht mit Burkhalt im Proszenium.", completion = "Wir haben entschieden, dass dies das Mindeste ist, um Euch dafür zu danken, dass Ihr Eure Erfahrung mit uns geteilt habt.\n\nIch habe selbst noch so vieles zu lernen. Also bitte macht bei noch einem Stück mit.", sourceObjectiveStatus = "unverified-source-field" }
quests[82785] = { id = 82785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritus ex machina", description = "Direkt unter uns ist ein Verteiler? Vielleicht hat Arbauch es da versteckt... Vergesst es, wir müssen uns das ansehen.\n\nMit etwas Glück ist Arbauch immer noch dort. Der Eingang sollte im Norden liegen, in der Nähe der Pfütze aus dem kaputten Rohr. Bitte kommt mit. Vielleicht braucht er unsere Hilfe.\n\nIch erkläre alles, wenn wir ihn gefunden haben.", sourceObjective = "Findet Vorarbeiter Arbauch.", completion = "Er hat ihn getötet, und wir haben ihn losgelassen. Selbst sein Erinnerungsedelstein fehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82786] = { id = 82786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürsorgepflicht", description = "Der Golem ist instabil. Ich bezweifle, dass er sich weit bewegen kann. Wir werden ihn verfolgen, aber Eile hat mich schon öfter scheitern lassen. Arbauch zeigte wahre Hingabe für die Maschinen - wir werden seinem Beispiel folgen. Reparaturen müssen an erster Stelle stehen.\n\nDie Maschinensysteme sind empfindlich. Wir müssen das Backup aktivieren, bevor ein Ausfall kaskadiert. Vernichtet auch alle Schädlinge, die Ihr findet. Selbst das kleinste Lebewesen kann solch empfindliche Maschinen zerstören!\n\nIch bin beschädigt. Ich werde meinen Radläufer mit Euch schicken, um Anweisungen zu übermitteln.", sourceObjective = "Aktiviert die Reservesysteme am Kataraktfluss.", progress = "Unsere Primäraufgabe ist die Wartung.", completion = "Die Reservesysteme sind in Betrieb. Jetzt können wir den Golem aufspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[82787] = { id = 82787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Aufstieg der Kolosse", sourceObjective = "Tötet kolossale Bestien", sourceObjectiveStatus = "unverified-source-field" }
quests[82792] = { id = 82792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "H-erz-ensangelegenheit", description = "Fremdling, Eure Hilfe ist vonnöten. \n\nDie Irdenen hier haben gesagt, Ihr wärt eine große Hilfe.\n\nUnsere irdenen Kameraden in der Opalgrube haben ihre Quote für den letzten Tag nicht gemeldet. Gewiss verursacht da etwas eine Störung.\n\nWürdet Ihr Vorarbeiter Alvegar einen Besuch abstatten?", sourceObjective = "Geht zur Opalgrube und sucht nach Alvegar.", completion = "Ich verstecke mich... bleibt unauffällig. \n\nHat Vorarbeiterin Germira Euch geschickt? Sie muss sich Sorgen machen, weil wir unsere Quote nicht geschickt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[82796] = { id = 82796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller guten Dinge sind drei", description = "Ich wurde vom Rest der Besatzung abgeschnitten. Wir haben nicht damit gerechnet, von Nerubern angegriffen zu werden. Ich kann mir aber nicht vorstellen, dass der Rest sich geschlagen gibt.\n\nUnsere Aufgabe ist zu wichtig, um jetzt aufzugeben. \n\nDirekt in die Mine zu stürmen könnte die Neruber in Raserei versetzen und den anderen schaden. Also habe ich einen dritten Weg gefunden, um früher hineinzukommen. Es wird trotzdem schwierig sein, unentdeckt zu bleiben.\n\nFolgt mir.", sourceObjective = "Trefft Alvegar am dritten Eingang zur Opalgrube.", completion = "Ihr habt es geschafft, nicht entdeckt zu werden, gut. Zeit, die Neruber zu überraschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[82797] = { id = 82797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Boden", description = "Es ist zwar ein langer Weg nach unten, aber Ihr könnt ihn sicher bewältigen.\n\nFalls Ihr Zweifel hegen solltet, habe ich ein paar Fallschirme gebastelt, die Euch bei der Landung helfen.\n\nWenn Ihr unten in der Höhle angekommen seid, haltet Ausschau nach Cenderragg. Sie ist die Älteste der Gruppe und hat wahrscheinlich die beste Idee, wie man das Team retten kann.", sourceObjective = "Trefft Cenderragg am Grund der Höhle.", completion = "Wer seid Ihr und warum seid Ihr hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[82798] = { id = 82798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Opale", description = "Ich will ehrlich sein. Wir verfolgen hier ein Ziel, und in dessen Fokus stehen die Opale.\n\nNiemand wird gehen, bevor wir den Auftrag erledigt haben - dazu sind die Opale zu wichtig. Wenn Ihr genug Erz sammelt, können wir sie überzeugen, zu gehen.\n\nAber seid vorsichtig, diese Neruber sind gefährlich.", sourceObjective = "Helft Cenderragg, 8 Stücke Opalerz in der Opalgrube zu sammeln.", progress = "Warum mussten die Neruber auftauchen? Wir waren fast fertig.", completion = "Wir haben viel gesammelt. Ich habe Sorge, dass es noch immer nicht reicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82799] = { id = 82799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netz schlägt Stein", description = "Ach, Vorarbeiter Alvegar hat Euch geschickt? Das erklärt Einiges.\n\nDie Lage ist unschön. Hier wimmelt es von Nerubern, und sie zeigen keine Gnade. Sie haben uns zur Minenarbeit gezwungen und unsere schwer erarbeiteten Opale gestohlen.\n\nWer nicht gehorcht, den spinnen sie ein.\n\nIch konnte ihnen gerade noch entkommen. Was die anderen betrifft... nun, da kommt Ihr ins Spiel.\n\nWenn Ihr sie hier ablenkt, kann ich die eingesponnenen Irdenen einsammeln.", sourceObjective = "Rettet 6 Arbeiter der Irdenen in der Opalgrube.", completion = "Der Maschine sei Dank! Sie sind frei!", sourceObjectiveStatus = "unverified-source-field" }
quests[82800] = { id = 82800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sedimentaler Moment", description = "Einige haben mit der Evakuierung begonnen, aber es gibt ein paar Hartnäckige, die einfach nicht loslassen können.\n\nKönntet Ihr etwas sagen?\n\nVielleicht bringt die Perspektive eines Fremdlings sie zum Handeln.", sourceObjective = "Helft Cenderragg, die irdenen Arbeiter in der Opalgrube zu inspirieren.", completion = "Es hat geklappt! Ich danke Euch. \n\nJeder gerettete Irdene ist ein großer Erfolg für uns alle. Egal, wie viel Zeit wir noch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[82801] = { id = 82801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juwelenkäfer", description = "Um sicherzugehen, dass keine weiteren Irdenen verletzt werden, müssen wir ihren Anführer beseitigen.\n\nWie lautet das Sprichwort? \"Wo der Schäfer fehlt, zerstreut sich die Herde.\"\n\nSo oder so, um uns in Sicherheit zu bringen, müssen wir durch sie hindurch.", sourceObjective = "Besiegt Kix'arak vor der Opalgrubenmine.", completion = "Ihr habt es zurückgeschafft, ich dachte schon, jede Hoffnung sei verloren.\n\nAlvegar hat mich über das Problem informiert. Ich bin nur froh, dass unsere Leute alle in Sicherheit sind, und wir haben sogar den Opal bekommen.\n\nEin kleiner Sieg, aber ein Sieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[82809] = { id = 82809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommt ein Greif geflogen", description = "Seid gegrüßt! Wie ich sehe, habt Ihr eine Sturmkrähe, die recht bedrückt dreinschaut. Schauen wir mal, ob wir sie nicht aufheitern können.", sourceObjective = "Findet einen Weg, Pusti aufzumuntern.", progress = "Kräh wah?", completion = "<Pusti zwitschert vor Freude und hüpft aufgeregt umher.>", sourceObjectiveStatus = "unverified-source-field" }
quests[82810] = { id = 82810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefundene Zeit", description = "Ihr seid wieder da!\n\nWenn Ihr Lust habt, im Schlamm wartet noch mehr. Aber Ihr müsst dieses Mal vermutlich etwas tiefer graben.", sourceObjective = "Findet 6 verlorene Andenken.", progress = "Was habt Ihr gefunden?", completion = "Genau wie vorher werde ich Euch ein paar Dinge geben, deren Besitzer wir vielleicht finden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[82813] = { id = 82813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geborgte Zeit", description = "Ah, da ist ja <mein guter Freund/meine gute Freundin>! Ich und Pläppi sind immer noch hier und suchen nach Erinnerungen. Habt Ihr einen Moment Zeit, um zu helfen?", sourceObjective = "Findet 6 verlorene Andenken.", progress = "Was habt Ihr gefunden?", completion = "Die haben ganz sicher eine Geschichte. Seht mal, ob Ihr den Besitzer findet.\n\nUnd danke. Ich weiß nicht, ob wir noch viel mehr finden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[82814] = { id = 82814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelheit stilllegen", description = "Eine Maschine stillzulegen, ist selten nötig. Der Akt muss mit Sorgfalt und Bedauern vollzogen werden.\n\nWir stecken viel von uns selbst in unsere Arbeit. Wenn wir sie dann zerstören, zerstören wir einen Teil von uns selbst. Damit gestehen wir unser Scheitern ein, das Werk der Titanen zu beschützen. Aber wo Stein gegen Stein rebelliert, müssen wir standhaft bleiben.\n\nBefehl: Maschine zerstören. Arbauchs Erinnerungsedelstein erlangen.", sourceObjective = "Zerstört den verderbten Golem und bergt den Erinnerungsedelstein von Vorarbeiter Arbauch.", progress = "Bedauern. Dies hätte meine Bürde sein sollen.", completion = "Im Tod einer Maschine liegt keine Freude, doch ich möchte meine Dankbarkeit ausdrücken. Das würde Arbauch wohl auch tun. \n\nEr hat seine Entscheidung getroffen, aber niemand kann bestreiten, dass er sein Leben den Maschinen gewidmet hat. Die Titanen wären stolz auf ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[82815] = { id = 82815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robustes Medaillon", progress = "Was habt Ihr denn da?", completion = "Wartet... Dieses Medaillon." }
quests[82817] = { id = 82817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störung entdeckt: Schwarzfelstiefen", description = "Die Zeitwanderer melden, dass sie in den Schwarzfelstiefen ein zeitversetztes Objekt gefunden haben.\n\nAuch wenn dieser Kampf in unserer Niederlage geendet hat, weiß der Dunkeleisenklan, was auf dem Spiel steht, sollte die Geschichte sich ändern. Wir könnten die aktuelle Zwergenallianz und all das Gute, das sich daraus ergeben hat, verlieren.\n\nBergt das Objekt und wahrt unseren gegenwärtigen Frieden.", sourceObjective = "Bergt die zeitverzerrten Baupläne aus Eisenschmiede von Imperator Thaurissan in den Schwarzfelstiefen.", progress = "Habt Ihr das zeitversetzte Objekt bergen können?", completion = "Es fühlt sich merkwürdig an, Euch für den umfassenden Sieg über meinen Klan zu danken. Doch aus der Asche haben wir uns erhoben\n\nVielen Dank, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[82832] = { id = 82832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hölzerne Figur", progress = "Habt Ihr ein Katzenproblem?", completion = "Och, die ist aber niedlich. Ich kann Euch nicht sagen, wo sie herkommt, sie scheint aber eher von einem Hobbyheimwerker als einem Künstler zu stammen. Ich stelle sie trotzdem aus." }
quests[82835] = { id = 82835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalzifiziertes Tagebuch", progress = "Sucht Ihr jemanden?", completion = "Ah! Das habe ich seit Jahren nicht mehr gesehen..." }
quests[82836] = { id = 82836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xeroshs Tribunal", sourceObjective = "Besiegt Belagerungsfürstin Xerosh.", progress = "Konntet Ihr die Belagerungsfürstin besiegen?", completion = "Jetzt, wo die Anführerin der Neruber besiegt wurde, können wir die Verteidigung vermutlich den Arathi überlassen.\n\nIhr habt heute viele Leben gerettet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[82843] = { id = 82843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Irdenes", description = "Ah, noch einer von der Sorte, was? Tja, wenn Ihr was zu essen wollt, müsst Ihr mit anpacken.\n\nPflückt mir einen Taro, ja?", sourceObjective = "Erntet für den Koch eine Taropflanze in der Nähe.", progress = "Habt Ihr den Taro dabei?", completion = "Oh. Tja ... Ihr habt es versucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82844] = { id = 82844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas nicht Ruiniertes", description = "Na schön, ich komme mit Euch mit. Damit Ihr mal seht, wie es richtig geht. Wenn ich mich schon aufmache, können wir gleich Taro bevorraten. Bei so delikaten Aufgaben kann man sich wohl nicht auf Abenteurer verlassen.", sourceObjective = "Erntet 6 Taropflanzen mit dem Koch. Aber diesmal bitte ordentlich.", progress = "Sind das alle?", completion = "Viel besser. Das reicht für eine Weile. Aber wenn Ihr was essen wollt, brauche ich noch etwas mehr Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[82845] = { id = 82845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elfenbeinzunderkasten", progress = "Was führt Euch ins Priorat, Fremdling?", completion = "Ein verlorener Gegenstand?\n\nDas gehört mir, und verloren wurde es nicht gerade." }
quests[82846] = { id = 82846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbeulte Speerspitze", progress = "So treffen wir uns wieder. Wie kann ich Euch helfen?", completion = "Ah, ich dachte, ich hätte es verlegt." }
quests[82847] = { id = 82847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug Knoblauch", description = "Normalerweise würde das ausreichen. Ich bin da nicht so wählerisch. Aber Ihr seid ein Gast. Also brauchen wir etwas Knoblauch.\n\nIch habe welchen auf einem Hügel in der Nähe gesehen. Sollte eigentlich nicht da sein. Ist er aber.\n\nSchade, dass die Hydras ihn auch gefunden haben.\n\nWaffen und so habt Ihr ja, oder?", sourceObjective = "Sammelt Knoblauch für den Koch.", progress = "Meint Ihr, das reicht?", completion = "Ah, sieh an. Das ist genug Knoblauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[82848] = { id = 82848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gehilfe", description = "Na schön, jetzt helft mir bei der Zubereitung.", sourceObjective = "Helft dem Koch, eine Mahlzeit zuzubereiten. Stellt Euch an den Tisch des Koches und setzt Zubereitungsfähigkeiten ein, um zu helfen.", progress = "Zeit zu kochen!", completion = "Danke, Fremdling. Es ist schön, etwas Gesellschaft zu haben. Da vergeht die Zeit gleich schneller. Viel Glück auf Euren Reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82849] = { id = 82849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filigraner Kleriker", progress = "Habt Ihr eine Bitte von der Küche?", completion = "Schaut Euch das an. Ich hatte mich schon gefragt, wo es sein könnte." }
quests[82852] = { id = 82852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Luchsrettung" }
quests[82894] = { id = 82894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis der Hoffnung", description = "{name}, es freut mich, Euch zu sehen. Ich bin gerade auf dem Weg zum örtlichen Lazarett. \n\n Möchtet Ihr mich begleiten?", sourceObjective = "Trefft Generalin Stahlstoß in im Lazarett von Mereldar.", progress = "Wir verlieren so viele, wir müssen alle retten, die wir retten können.", completion = "Danke. Wenn Ihr bald wiederkommen und Kaeleb helfen könntet, wäre ich sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[82895] = { id = 82895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bürde der Pflicht", description = "Ich bin jetzt die Verwalterin von Trauerhöhe.\n\nEndlich darf ich die Bürde dieser neuen Verantwortung auf meinen Schultern tragen. Es ist eine große Ehre, auf die ich mich sorgfältig vorbereiten muss.\n\nBitte helft mir, eine letzte Aufgabe abzuschließen. Dann werde ich bereit sein.\n\nTrefft mich am Fallsprungaußenposten wieder.", sourceObjective = "Trefft Urtago am Fallsprungaußenposten und helft ihr, ihre neue Rolle anzunehmen.", progress = "Noch eine Aufgabe, dann bin ich wahrhaft die Verwalterin.", completion = "Ihr habt Korgran in seinen letzten Momenten Frieden geschenkt, und nun habt Ihr mir geholfen, in seine Fußstapfen zu treten.\n\nIch werde Eure Hilfe nie vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82916] = { id = 82916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Pilze blüh'n", description = "Seid gegrüßt!\n\nVielleicht könntet Ihr mir etwas Fleißarbeit abnehmen? Ich habe so viele Bestellungen, dass ich mich um ein paar Einheiten Mykopracht verrechnet habe. Na ja, ehrlich gesagt um mehr als nur ein paar.\n\nWärt Ihr so gut und würdet den Rest für mich sammeln?", sourceObjective = "Sammelt für Akdan 20 Exemplare Mykopracht in Dornogal.", progress = "Ich will Euch ja nicht hetzen, aber ich brauche die Mykopracht so schnell es geht. Bitte.", completion = "Vielen Dank, {name}! Das sind wunderbare Exemplare.\n\nHier, ein kleines Dankeschön für Eure Zeit und Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[82946] = { id = 82946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In tiefsten Tiefen", description = "Wichtige Aufgabe für Euch, ja?\n\nSachen holen, ganz wachsig. Schnell herbringen, ja? Viel zu handeln für gute Funde.\n\nSchnüffelt los, <Freundchen/Liebchen>.", sourceObjective = "Sammelt 10 seltsame Wachsklumpen.", progress = "Fertig geschnüffelt, ja? Habt Ihr wachsige Sachen?", completion = "Ah, so schnell zurück! Zeigt mir wachsige Schätzchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82952] = { id = 82952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gelegenheit zur Entspannung", description = "Hey, Ihr da! Ja, Ihr solltet genügen. Wollt Ihr Euch bisschen Zaster verdienen? Wir wollen Werbung für unser exklusives Resort machen. Vielleicht habt Ihr davon gehört? Kur- und Baderesort Chancenspitze!\n\nChef hat mich nach Gundargaz geschickt, um diesen Stapel Flugblätter zu verteilen, aber an meinem Trike ist eine Dichtung geplatzt. Jetzt sitz ich hier fest, bis ich's repariert hab. Wie wär's, wenn Ihr stattdessen hingeht und die Zettel unters Volk bringt? Nehmt besonders die müden und ausgelaugten Leutchen ins Visier.", sourceObjective = "Verteilt 6 Flugblätter an erschöpfte Arbeiter in und um Gundargaz.", progress = "Ich hätt auf meinen Mechaniker hören sollen. Er hat mir klipp und klar gesagt, mein Trike schafft es nie im Leben bis hierher. Aber mein Chef saß mir im Nacken, von wegen neue Kunden akquirieren und so.\n\nHabt Ihr die Flugblätter schon verteilt?", completion = "Ihr seid zurück! Wie lief's? Müssen wir uns auf einen Riesenansturm vorbereiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[82953] = { id = 82953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine herzliche Einladung", description = "Mir ist jetzt klar, dass meine Zeit als Wesir sich ihrem Ende zuneigt. Ich muss Azj-Kahet künftig auf andere Weise dienen. Dazu habe ich eine letzte Bitte an Euch, {name}.\n\nIhr habt seit Eurer Ankunft in der Stadt der Fäden viel geleistet. Zweifellos eilt Euer Ruf Euch voraus. Sucht unsere Verbündeten in der Stadt auf und bittet sie, sich am Umbralbasar zu versammeln. Ich habe eine Botschaft für sie vorbereitet.", sourceObjective = "Gebt den Leuten in der Stadt der Fäden Bescheid, dass der Wesir eine Bekanntmachung hat.", progress = "Etwas schneller, bitte. Wir haben nicht viel Zeit.", completion = "Ihr habt eine beachtliche Menge herbeigerufen. Ausgezeichnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[82954] = { id = 82954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messer in der Dunkelheit", description = "Ihr erinnert Euch sicher an den Assassinen, der mich töten wollte, als wir uns das letzte Mal an diesem Ort begegnet sind. Hättet Ihr damals nicht eingegriffen, wäre ich heute nicht hier. Täuscht Euch nicht: Wenn meine Rolle in der ganzen Sache kompromittiert wurde, wird dieser Attentäter nicht der letzte gewesen sein.\n\nWenn ich mein letztes großes Aufgebot machen will, brauche ich Eure Hilfe, damit ich bis zur letzten Stunde geschützt bin. Durchsucht die Stadt nach mehr von diesen lauernden Bedrohungen und tut, was nötig ist, damit sie meine Rede nicht stören können.", sourceObjective = "Tötet 4 Attentäter der Sureki in der Stadt der Fäden.", progress = "Bitte geht gründlich vor, mein Freund. Ich würde ungern heute erstochen werden.", completion = "Präventive Gewalt ist etwas schäbig, finde ich. Aber angesichts der Umstände war die Reaktion angemessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82955] = { id = 82955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entschlossenheit des Wesirs", description = "Die Bühne ist bereit, die Spieler sind versammelt. Es wird Zeit, dass ich aus den Schatten trete.\n\nDanke, dass Ihr bis hierhin an meiner Seite wart, {name}. Was auch geschieht, ich bin dankbar, Euch kennengelernt zu haben.", sourceObjective = "Lauscht der Rede des Wesirs auf dem Umbralbasar.", completion = "Es ist vollbracht. Und damit ist ein Kapitel meines Lebens abgeschlossen.\n\nIch hoffe, unsere Stadt kann mit neuerlicher Entschlossenheit in die Zukunft blicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[82956] = { id = 82956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Chancenspitze", description = "Ein Glück, dass das erledigt ist. Jetzt muss mein Chef mir nicht Dampf machen!\n\nIch hab noch ein paar Reparaturen an meinem Gefährt vor mir, aber Ihr solltet mal an der Chancenspitze vorbeigehen und es Euch anschauen. Ich geb Euch sogar einen Getränkegutschein für unser feines Etablissement mit.\n\nWendet Euch einfach an Griz Fingelbur und er versorgt Euch.", sourceObjective = "Trinkt etwas an der Chancenspitze.\n\nBereitgestellter Gegenstand:", completion = "Willkommen an der Chancenspitze! Ihr habt einen Getränkegutschein für lau, wie? Kommt sofort!", sourceObjectiveStatus = "unverified-source-field" }
quests[82957] = { id = 82957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danke für das Wachs" }
quests[82958] = { id = 82958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Segen", description = "Ihr da!\n\nMeine Vorräte an Segensblumen gehen zur Neige, und bevor die neue Lieferung kommt, gehen sie mir ganz aus.\n\nKann ich Euch vertrauen, die Kräuter für mich zu sammeln?", sourceObjective = "Sammelt für Akdan 10 Segensblumen in Dornogal.", progress = "Konntet Ihr die Kräuter für mich finden?", completion = "Aha! Gute Arbeit. Ich bin froh, dass ich Euch diese Aufgaben anvertrauen kann.\n\nIch habe eine Kleinigkeit für Euch. Nichts Großes, aber es erweist sich bestimmt noch als nützlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[82959] = { id = 82959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie Hügelpinne: Das verlorene Tagebuch", description = "<Das Tagebuch scheint Aliya Hügelpinne zu gehören. Es wäre unhöflich, es zu lesen. Gebt es Ihr am besten einfach zurück.>", sourceObjective = "Bringt das verlorene Tagebuch zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Ach je, das Tagebuch habe ich schon vor einer Weile verloren.\n\nEinige Dinge, die ich hineingeschrieben habe, sind mir inzwischen ziemlich unangenehm. Und ehrlich gesagt sind manche Geschichten auch gar nicht wahr!", sourceObjectiveStatus = "unverified-source-field" }
quests[82960] = { id = 82960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie Hügelpinne: Lilys Medaillon", description = "<Dieses Medaillon muss jemandem viel bedeuten. Vielleicht kann Aliya Hügelpinne etwas Licht ins Dunkel bringen.>", sourceObjective = "Bringt Lilys Medaillon zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt es gefunden! Das ist Lilys Medaillon. Sie hat es in dem Zeitraum verloren, in dem Tante Gerta ihren Unfall hatte.\n\nWir haben überall danach gesucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82961] = { id = 82961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie Hügelpinne: Das Huhn", description = "<Ihr solltet dieses ausgebüxte Huhn vermutlich zu Aliya Hügelpinne am Hügelpinnenhof zurückbringen.>", sourceObjective = "Bringt das Huhn zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Oh, Wilber, du verrücktes Huhn! Dich findet man immer an den merkwürdigsten Orten!\n\nTante Gerta hat Wilber immer gejagt und nach ihren Verstecken gesucht. Danke, dass Ihr sie wieder nach Hause gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[82962] = { id = 82962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reizvolle Reiztropfen", description = "Ihr da, ja Ihr.\n\nHabt Ihr schon mal vom Reiztropfen gehört? Das ist eine seltene fleischfressende Pflanze, die sich von Insekten ernährt. Wir haben keine Insekten hier, aber ich wünschte, wir hätten einige Exemplare. Falls Ihr welche findet, sagt mir doch Bescheid, oder noch besser: Bringt sie mir.", sourceObjective = "Sammelt für Akdan 3 Reiztropfen in Dornogal.", progress = "Denkt dran, die findet man nur selten.", completion = "Ach, sieh mal einer an! Das sind wunderbare Exemplare.\n\nWir zwei sollten ein Geschäft aufmachen. Ich verkaufe und Ihr besorgt die Waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[82963] = { id = 82963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie Hügelpinne: Das kleine Schweinchen", description = "<Ihr solltet dieses kleine Schweinchen vermutlich zu Aliya Hügelpinne am Hügelpinnenhof zurückbringen.>", sourceObjective = "Bringt das kleine Schweinchen zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Das kleine Schweinchen war seit Tagen verschwunden, aber ich habe noch die Hoffnung bewahrt, dass es seinen Weg nach Hause findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[82964] = { id = 82964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie Hügelpinne: Onkels Auge", description = "<Ein Glasauge, ein ziemlich wertvoller Gegenstand. Vielleicht hat Aliya Hügelpinne eine Ahnung, wer es verloren hat.>", sourceObjective = "Bringt Onkels Auge zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Ist das das Auge von Onkel Tomas?\n\nEr hat so die Angewohnheit, es jedes Mal zu verschusseln, wenn er in den Feldern spazieren geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[82965] = { id = 82965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht und Schatten", description = "Mir fehlen zwei Kräuter.\n\nDas erste ist Arathors Speer und das zweite, und das viel seltenere, ist Orbinid.\n\nMir ist schon klar, was Ihr jetzt denkt: Die sind beide ziemlich selten. Ja, bis zu einem gewissen Grad, aber ich brauche auch nicht viel und die Bezahlung macht jede Mühe wett.\n\nWas meint Ihr? Kann ich Euch diese Aufgabe anvertrauen?", sourceObjective = "Sammelt für Akdan 5 Exemplare Arathors Speer und 5 Exemplare Orbinid in Dornogal.", progress = "Habt Ihr beide besorgt?", completion = "Ich wusste es!\n\nWenn es um Kräuter geht, seid Ihr der beste Lieferant, den ich je hatte.\n\nHier, nehmt dies. Das ist das Mindeste, was ich tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[82966] = { id = 82966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie Hügelpinne: Die außergewöhnliche Kartoffel", description = "<Diese Kartoffel hat eine ungewöhnliche Form. Sie sieht fast wie eine Berühmtheit aus. Aliya Hügelpinne will sie bestimmt sehen!>", sourceObjective = "Bringt die ungewöhnliche Kartoffel zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Diese Kartoffel ist unglaublich. Es ist fast, als würde uns Generalin Stahlstoß persönlich gegenüberstehen!\n\nIch werde sie im Haus ausstellen, damit sie jeder sehen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[82967] = { id = 82967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie Hügelpinne: Das Ohr", description = "<Eine absolut entsetzliche Entdeckung. Ihr solltet sie rasch Aliya Hügelpinne am Hügelpinnenhof zeigen.>", sourceObjective = "Bringt das Ohr zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "So makaber es auch sein mag, ich bin froh, dass Ihr sie gefunden habt. Nach dem Unfall haben wir Teile von Gerta überall auf den Feldern verstreut gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[82968] = { id = 82968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie Hügelpinne: Die Pflugspitze", description = "<Eine Pflugspitze in makellosem Zustand. Aliya Hügelpinne am Hügelpinnenhof könnte sicher etwas damit anfangen.>", sourceObjective = "Bringt die Pflugspitze zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Oh, vielen Dank. Die wird sehr nützlich sein. Viele unserer Pflugspitzen wurden beschädigt, als die Erntemaschine durchgedreht ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[82969] = { id = 82969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestein auf der Spur", description = "Ich konnte nicht anders, als mitzuhören. Ich will ja nicht angeben, aber Goblins sind Experten, wenn es um wildgewordene Roboter geht.\n\nWenn der Golem so instabil ist, wie Danagh behauptet, läuft bestimmt jede Menge Energie aus. Nehmt dies, führt einige Scans durch, dann werdet Ihr ihn schon finden. Oh, und seid vorsichtig. Tiere drehen leicht durch, wenn man das Ding anschaltet.\n\nDas kostet nichts, ein mordlüsterner Golem ist schlecht fürs Geschäft. Und ich fühle mich schlecht, weil ich Euch zur Suche nach einem Toten verpflichte.", sourceObjective = "Scannt Überreste des Golems, um seinen Aufenthaltsort zu bestimmen.", completion = "Merkwürdig. Er schien am Fluss unterwegs zu sein. Macht nichts, wir haben seinen Aufenthaltsort. Wir finden ihn und nehmen ihn außer Betrieb.", sourceObjectiveStatus = "unverified-source-field" }
quests[82970] = { id = 82970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blumenpracht", description = "He, Ihr da!\n\nIch habe eine Aufgabe für Euch.\n\nIch benötige eine Handvoll Mykopracht und einige Segensblumen. Wenn Ihr der Aufgabe gewachsen seid, erwartet Euch ein großzügiger Lohn.", sourceObjective = "Sammelt für Akdan 10 Exemplare Mykopracht und 10 Segensblumen.", progress = "Ich habe Eure Belohnung schon beiseitegelegt. Sie wartet auf Euch, sobald Ihr mir die Kräuter beschafft.", completion = "Der Berg segne mich!\n\nMit Euch mache ich gern Geschäfte.", sourceObjectiveStatus = "unverified-source-field" }
quests[82971] = { id = 82971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warteschlangenbonus" }
