quests[82980] = { id = 82980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warteschlangenbonus" }
quests[82990] = { id = 82990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schadenswiedergutmachung", description = "Entschuldigung. Arbauch war nicht für Reparaturen hier. Er hat den Golem gestohlen.\n\nArbauch und ich haben jahrelang mit dem Ding in den dunkelsten Ecken der Tiefen gearbeitet, und das hat dem Golem zu schaffen gemacht. Er wurde unberechenbar, sogar gefährlich. Wir wollten ihn außer Betrieb nehmen, aber als der Zeitpunkt gekommen war, hielt Arbauch es nicht aus. Er hatte ihn lieb gewonnen. Bevor ich ihn zerstören konnte, ist Arbauch mit dem Golem geflohen.\n\nWir müssen ihn finden, aber der Schaden am Verteiler ist drastisch. Mit Eurer Hilfe kann ich versuchen, das zu reparieren.", sourceObjective = "Verteidigt Danagh, während er den Verteiler repariert.", completion = "Ein Vorarbeiter und ein Verteiler verloren. Verflucht. Ich war unvorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[82992] = { id = 82992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmgeladene Waren", description = "Ich grüße Euch, <Geselle/Gesellin>.\n\nIch bin auf der Suche nach tatkräftiger Unterstützung für eine kleine Besorgung. Mir gehen langsam die Waren aus und ich habe seit einiger Zeit nichts mehr von meinem Lederlieferanten gehört. Wenn ich keine Häute und kein Leder besorge, können die Lederarbeiter keine Bekleidung fertigen.\n\nIch belohne Euch gern, wenn Ihr mir mehrere Exemplare sturmgeladenes Leder beschafft.", sourceObjective = "Sammelt 20 Exemplare sturmgeladenes Leder und bringt sie zu Ginnad in Dornogal.", progress = "Habt Ihr gute Neuigkeiten? Von meinem Lederlieferanten habe ich immer noch nichts gehört.", completion = "Ihr habt das Leder? Den Titanen sei Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[82993] = { id = 82993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Schatten", description = "Hallöchen!\n\nIch habe von wundersamen Stoffen gehört, die man offenbar aus etwas... ungewöhnlichen Materialien weben kann.\n\nWenn Ihr gern durch die letzten sonnigen Gegenden von Khaz Algar reist, würdet Ihr mir wohl Kahetischwarmchitin und sonnenlose Panzer sammeln? Ich belohne Euch natürlich, wenn Ihr mir einige Proben bringt.", sourceObjective = "Sammelt 5 Exemplare Kahetischwarmchitin und 5 sonnenlose Panzer und bringt sie zu Ginnad in Dornogal.", progress = "Ich bin ziemlich gespannt, diese Materialien in die Hände zu bekommen.", completion = "Wie außergewöhnlich. Ich vermag nicht zu sagen, was man mit diesen Materialien erreichen kann. Das wird nur die Zeit zeigen, so die Titanen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[82994] = { id = 82994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachsbeitrag" }
quests[82995] = { id = 82995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das nerubische Gerät", description = "Ein seltsames Gerät nerubischen Ursprungs. Aevery Flammenzunge am Hügelpinnenhof fände es sicher faszinierend.", sourceObjective = "Bringt das nerubische Gerät zu Aevery Flammenzunge am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Das ist unglaublich faszinierend.\n\nEs ist möglich, dass die Neruber mit diesem Gerät Spinnen und andere Kreaturen manipulieren, damit sie es auf unsere Höfe absehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83023] = { id = 83023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungen sind knapp" }
quests[83024] = { id = 83024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmreiterbande", description = "Ihr glaubt also, dass Ihr einer Sturmreiterrüstung würdig seid?\n\nWir Sturmreiter wurden von den Titanen geschaffen, um zu kämpfen und auf Sturmkrähen zu reiten. Dennoch müssen wir unser Geschick im Kampf unter Beweis stellen, bevor uns gestattet wird, Sturmreiterrüstung zu tragen. Ich wüsste nicht, warum Ihr nicht die gleiche Herausforderung meistern solltet.\n\nNa los. Zeigt mir, dass Ihr die Macht des Sturms in Euch tragt.", sourceObjective = "Erschlagt mächtige Kreaturen in Khaz Algar und sammelt 50 Sturmgeister.", progress = "Kommt zurück, wenn Ihr Euch als würdig erwiesen habt.", completion = "Hm. Erlaubnis erteilt.\n\nDiese Rüstung ist eigentlich Sturmreitern vorbehalten. Aber für Euren Heldenmut gewähre ich Euch eine Sondergenehmigung. Tragt sie mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[83025] = { id = 83025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine heilige Verbindung", description = "Ich mag Euch Erlaubnis erteilt haben, unsere Rüstung zu tragen, aber um mit ihr die Macht des Sturms zu konzentrieren, wie unsere mächtigsten Sturmreiter es können...\n\nDie besten Sturmreiter in unseren Reihen besitzen die Macht des Sturms nicht bloß. Sie haben sie gemeistert. Und diese Meisterschaft wird in vielen Kämpfen gestählt.\n\nEs wird Zeit, dass Ihr Euch als einer unserer Besten erweist.", sourceObjective = "Erschlagt mächtige Kreaturen in Khaz Algar und sammelt 500 Sturmgeister.", progress = "Euer Lohn soll Euren Mühen gerecht werden.", completion = "Ja. Das ist die Meisterschaft, die nur unsere mächtigsten Sturmreiter zeigen. Möge diese Rüstung der Beweis ein.\n\nTragt Eure Rüstung mit Stolz. Es ist eine Ehre, die man nicht leichtfertig abtun sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[83026] = { id = 83026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SNGDungeons - TWW - Heroischer Dungeon - Erster" }
quests[83028] = { id = 83028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Schnüffler" }
quests[83031] = { id = 83031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwierigste Teil", description = "<Aethas seufzt tief. Trauer liegt in seiner Stimme.>\n\nDalaran, einst ein Symbol von Einigkeit und arkaner Überlegenheit, liegt in Schutt und Asche. Schon wieder.\n\nSo viel Verlust und so viel Schmerz. Freunde und Kameraden, von jetzt auf gleich verschwunden, ihre Stimmen von Xal'atath erstickt.\n\n<Er holt tief Luft und verschließt sich vor der überwältigenden Trauer.>\n\nDoch jetzt ist Zeit zu handeln, nicht für Tränen. Wir müssen uns mit den übrigen Kirin Tor sammeln.\n\nDie richtigen Worte zu finden, ist gar nicht so leicht.", sourceObjective = "Helft Aethas Sonnenhäscher, den überlebenden Magiern der Kirin Tor am Ruhigen Ufer eine Nachricht zu schicken.", progress = "Was sagt man an solchen Tagen?", completion = "Endlich haben wir den ersten Schritt getan.\n\nJetzt müssen wir warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[83040] = { id = 83040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NICHT BENUTZEN" }
quests[83043] = { id = 83043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschnitzte Wappen", sourceObjective = "Dankbarkeit wird ausgedrückt. Bitte nehmt dies als Belohnung für all Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[83046] = { id = 83046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschnitzte Wappen", sourceObjective = "Dankbarkeit wird ausgedrückt. Bitte nehmt dies als Belohnung für all Eure harte Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
