quests[83055] = { id = 83055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterschrieben und versiegelt" }
quests[83057] = { id = 83057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzen setzen", description = "Vi'azl hat ein Maß an Folter erlebt, das ich noch nicht kannte. Wir können Vi nicht bei seiner Furcht helfen, bis er wirklich in Sicherheit ist.\n\nWann immer möglich predige ich Freundschaft, Wiedergutmachung und Aussöhnung. Ich bitte andere, mit Empathie und Mitgefühl zu handeln. Jeder verdient eine Chance, wieder das Licht zu sehen. Diesen Idealen habe ich mein Leben gewidmet.\n\nAber wenn ich höre und sehe, was mit Vi'azl geschieht ... Ich glaube, ich habe meine Meinung geändert. Genug ist genug. Wir müssen etwas unternehmen.", sourceObjective = "Tötet den Aufgestiegenen Neruber, der Vi'azl foltert.", progress = "Niemand hat so eine Tortur verdient.", completion = "Diese Aufgestiegenen Neruber sind so weit mutiert, dass sie jegliches Mitgefühl und jeden Sinn für Gemeinschaft verloren haben. Es schmerzt mich, aber ich muss mich auf jene konzentrieren, die noch gerettet werden können, Vi'azl zum Beispiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[83069] = { id = 83069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Titanischer Rückstrom" }
